const ozSocialscience13Orta = <(String, String, List<String>, String)>[
  ('\'Üçgen\' terimine \'iç açıları eşit\' niteliği eklenerek \'eşkenar üçgen\' elde edildiğinde mantıksal olarak ne olmuştur?', 'İçlem artmış, kaplam azalmıştır', ['İçlem azalmış, kaplam artmıştır', 'Hem içlem hem kaplam artmıştır', 'Hem içlem hem kaplam azalmıştır'], 'Yeni nitelik içlemi artırır; bu niteliği taşıyan üçgen sayısı az olduğundan kaplam daralır.'),
  ('\'Bütün öğretmenler okur-yazardır\' önermesinde \'öğretmen\' terimi için hangisi doğrudur?', 'Tüm kaplamıyla alınmıştır', ['Kaplamının yalnız bir kısmıyla alınmıştır', 'Hiç kaplamı yoktur', 'Tekil terim olarak, yalnız tek bir öğretmeni gösteren biçimde kullanılmıştır'], 'Tümel önermede konu terimi kaplamının tamamıyla alınır; öğretmen sınıfının her üyesi hakkında hüküm verilmiştir.'),
  ('\'Dünyanın en yüksek dağı\' ifadesi mantıkta hangi terim türüne girer?', 'Tekil terim', ['Topluluk terimi', 'Soyut terim', 'Yoksun terim'], 'İfade tek bir bireyi (Everest) belirtir; kaplamında yalnız bir üye bulunan terimler tekil terim sayılır.'),
  ('\'Sessizlik, gürültünün olmadığı durumdur\' tanımı hangi tanım kuralına aykırıdır?', 'Tanım mümkün olduğunca olumlu ifadelerle yapılmalıdır', ['Tanım, tanımlananla aynı kaplama sahip olacak biçimde tam eşit olmalıdır', 'Tanım mecaz içermemelidir', 'Tanım cins içermelidir'], 'Gerekli olmadıkça olumsuz terimle tanım yapılmaz; olumsuz tanım bir şeyin ne olduğunu değil ne olmadığını gösterir.'),
  ('\'Dolar\' sözcüğünün Türkçede \'Amerikan para birimi\' anlamında nasıl kullanıldığını gösteren sözlük girdisi hangi tanımdır?', 'Betimleyici (bildirici) tanım', ['Önerici tanım', 'İkna edici tanım', 'Örnekleme tanım: sözcüğü yalnızca birkaç örnek sayarak açıklayan tanım'], 'Bir sözcüğün gerçek dilsel kullanımını aktaran tanım betimleyicidir; doğru ya da yanlış olabilir.'),
  ('\'Taşıtlar: karayolu, havayolu ve çocuk taşıtları olarak ikiye ayrılır\' bölmesinde hangi kural çiğnenmiştir?', 'Bölme tek bir ölçüte göre yapılmalıdır', ['Bölünen terim, bölümlerinden her zaman daha dar kaplamlı olmalıdır', 'Bölüm sayısı ikiyi geçmemelidir', 'Bölme olumlu terimlerle yapılmalıdır'], 'Burada yol türü ve kullanıcı yaşı gibi iki ayrı ölçüt karıştırılmıştır.'),
  ('Bir bölmede bölümlerin birleşiminin bölünen terimin kaplamına eşit olması kuralı neyi sağlar?', 'Hiçbir üyenin dışarıda kalmamasını', ['Bölümlerin kesişmesini', 'Bölünenin içleminin artmasını', 'Bölümlerin sonsuza kadar alt bölümlere ayrılabilmesini'], 'Bölümlerin toplamı bölünenin tamamını karşılamalı; bölümler birbirinden ayrık olmalıdır.'),
  ('Kütüphanede kitapların aynı anda hem konuya hem yazar adının baş harfine göre dizilmeye çalışılması hangi bölme kuralıyla çelişir?', 'Tek ölçüt kuralı', ['Ayrık bölümler kuralı', 'Terim sayısı kuralı', 'Özdeşlik kuralı'], 'Bir sınıflandırmada tek ölçüt kullanılmazsa bölümler çakışır ve düzen bozulur.'),
  ('Carl von Linné\'nin canlıları cins ve tür adlarıyla ikili adlandırması hangi mantıksal çalışmaya örnektir?', 'Hiyerarşik sınıflandırma', ['Dolaylı kanıt', 'Safsata: geçersiz olduğu hâlde ikna edici görünen akıl yürütme', 'Paradoks'], 'Canlıların üst kategorilerden alt kategorilere dizilmesi, kaplamlara dayanan hiyerarşik sınıflandırmadır.'),
  ('\'Eğer 2 + 2 = 5 ise Ay peynirden yapılmıştır\' koşullu önermesinin doğruluk değeri nedir?', 'Doğru', ['Yanlış', 'Belirsiz', 'Önerme değildir'], 'Öncülü yanlış olan koşullu önerme, sonucun değeri ne olursa olsun doğrudur (boş doğruluk).'),
  ('\'p → q\' önermesinin doğru, q\'nun yanlış olduğu biliniyorsa p için ne söylenebilir?', 'Yanlıştır', ['Doğrudur', 'Belirsizdir', 'Hem doğru hem yanlış olabilir'], 'Sonucu yanlış olan doğru bir koşullunun öncülü yanlış olmak zorundadır (modus tollens).'),
  ('\'(p ∨ q) → p\' koşullu önermesi doğruluk tablosunun kaç satırında yanlıştır?', 'Yalnız bir satırında', ['Hiçbir satırında', 'Üç satırında', 'İki satırında, yani p\'nin yanlış olduğu bütün satırlarda'], 'Önerme yalnızca p yanlış, q doğruyken yanlıştır; çünkü o zaman p ∨ q doğru, p yanlış olur.'),
  ('p: \'Yağmur yağıyor\', q: \'Şemsiye açığım\'. \'Ne yağmur yağıyor ne de şemsiye açığım\' cümlesi sembolle nasıl yazılır?', '¬p ∧ ¬q', ['¬(p ∧ q)', '¬p ∨ ¬q', 'p ↓ ¬q'], '\'Ne ... ne de\' yapısı iki olumsuzun birlikte doğru olmasını bildirir; bu da ¬p ∧ ¬q\'dur.'),
  ('\'Hem p hem q olması söz konusu değildir\' ifadesi hangi sembolik biçimdedir?', '¬(p ∧ q)', ['¬p ∧ ¬q', 'p ∧ ¬q', '¬p ↔ q'], 'İki önermenin birlikte doğru olmasının reddi, ve bağlacının olumsuzudur.'),
  ('Aşağıdakilerden hangisi bir çelişmedir?', 'p ↔ ¬p', ['p → ¬p', 'p ∨ ¬p', '(p ∧ q) → p'], 'Bir önerme kendi olumsuzuna eşdeğer olamaz; p ↔ ¬p her değerde yanlıştır.'),
  ('\'Bir üçgenin eşkenar olması için üç açısının da 60° olması\' koşulu hakkında hangisi doğrudur?', 'Gerek ve yeter koşuldur', ['Yalnız gerek koşuldur', 'Yalnız yeter koşuldur', 'Ne gerek ne yeter koşuldur'], 'Üç açısı da 60° olan üçgen eşkenardır, eşkenar üçgenin açıları da 60°\'dir; koşul iki yönlü geçerlidir.'),
  ('\'Sınavı geçmek için en az 50 almak gerekir\' cümlesi (p: 50 almak, q: geçmek) hangi koşullu biçimdir?', 'q → p', ['p → q', 'p ↔ q', '¬q → p'], 'Gerek koşul, sonucun gerçekleşmesi için bulunması zorunlu şarttır: geçtiysem en az 50 almışımdır.'),
  ('\'Hiçbir sürüngen tüylü değildir. Bazı hayvanlar sürüngendir. O hâlde bazı hayvanlar tüylü değildir.\' kıyası için hangisi doğrudur?', 'Geçerlidir; Ferio kipine uyar', ['Geçersizdir; orta terim dağıtılmamıştır', 'Geçersizdir; iki olumsuz öncül vardır', 'Geçersizdir; dört terim kullanılmıştır'], 'Öncüller E ve I, sonuç O olduğundan birinci şekil Ferio\'dur; kıyas geçerlidir.'),
  ('\'Hiçbir kuş memeli değildir. Hiçbir yarasa kuş değildir. O hâlde hiçbir yarasa memeli değildir.\' kıyasının hatası nedir?', 'İki olumsuz öncülden sonuç çıkmaz kuralı çiğnenmiştir', ['Orta terim hiçbir öncülde dağıtılmamıştır ve kıyas bu yüzden geçersizdir', 'İki tikel öncül kullanılmıştır', 'Sonuç, öncüllerden daha güçlü bir önermedir'], 'Gerçekte yarasalar memelidir; kıyasın sonucu yanlış olduğu gibi biçimi de geçersizdir, çünkü iki olumsuz öncül hiçbir şey kanıtlamaz.'),
  ('\'Bütün çiçekler kokuludur. Bütün güller çiçektir. O hâlde bazı güller kokulu değildir.\' kıyasında hangi kural bozulmuştur?', 'İki olumlu öncülden olumsuz sonuç çıkmaz', ['Orta terim hiçbir öncülde dağıtılmamıştır', 'Dört terim kullanılmıştır', 'İki olumsuz öncül vardır'], 'Öncüller olumludur; sonuçtaki olumsuzluk öncüllerde kaynağı olmayan bir nitelik getirir.'),
  ('Bir kıyasta öncüllerden biri tikel, öteki tümel olumlu ise sonuç için hangisi geçerlidir?', 'Sonuç tikel olmalıdır', ['Sonuç tümel olmalıdır', 'Sonuç olumsuz olmalıdır', 'Sonuç çıkarılamaz'], 'Sonuç zayıf öncülü izler: öncüllerden biri tikelse sonuç da tikel olur.'),
  ('\'Bütün bilim insanları meraklıdır. Bütün filozoflar meraklıdır. O hâlde bütün filozoflar bilim insanıdır.\' kıyasında hata nedir?', 'Orta terim (\'meraklı\') hiçbir öncülde dağıtılmamıştır', ['Küçük terim sonuçta dağıtıldığı hâlde öncülde dağıtılmamıştır', 'İki olumsuz öncül vardır', 'Dört terim kullanılmıştır'], 'Her iki öncülde \'meraklı\' yüklem olduğundan dağıtılmamıştır; böylece öncüller iki kümenin aynı kümeyle bağlantısını gösterse de birbirleriyle ilişkisini göstermez.'),
  ('\'Bütün öğretmenler okur. Bazı yöneticiler öğretmendir. O hâlde bazı yöneticiler okur.\' kıyası hangi kipe girer ve geçerli midir?', 'Darii; geçerlidir', ['Ferio; geçerlidir', 'Darapti; geçersizdir', 'Barbara; geçersizdir'], 'A-I-I düzeninde birinci şekil Darii\'dir ve orta terim (\'öğretmen\') büyük öncülde dağıtıldığından geçerlidir.'),
  ('\'Canlı\' ve \'cansız\' terimleri arasındaki mantıksal ilişki nasıl adlandırılır?', 'Çelişik terimler', ['Karşıt terimler: aralarında orta dereceler bulunur', 'Özdeş terimler: kaplamları aynıdır', 'Kesişen terimler: ortak üyeleri vardır'], 'Bir terim ile onun olumsuzu evreni ikiye böler; canlı olmayan her şey cansızdır, orta bir durum yoktur.'),
  ('\'Sıcak\' ve \'soğuk\' terimleri arasındaki ilişki için hangisi söylenebilir?', 'Karşıttırlar', ['Çelişiktirler; her şey ya sıcaktır ya soğuktur', 'Özdeştirler; aynı şeyi farklı biçimde anlatırlar', 'Biri ötekini bütünüyle kapsar'], 'Karşıt terimler bir ölçeğin iki ucunu gösterir; ikisi birlikte doğru olamaz ama birlikte yanlış olabilir (ılık).'),
  ('\'Bütün A\'lar B\'dir\' ve \'Bütün B\'ler A\'dır\' ikisi birlikte doğruysa A ile B arasında nasıl bir ilişki vardır?', 'Kaplamları özdeştir', ['B, A\'nın alt kümesidir ama özdeş değildir', 'Kesişirler ama kapsamazlar', 'Ayrıktırlar'], 'Karşılıklı kapsama iki kümenin aynı üyelere sahip olduğunu gösterir; bu özdeşliktir.'),
  ('\'Hiçbir A, B değildir\' ve \'Bütün C\'ler A\'dır\' önermeleri doğruysa C ile B arasında ne söylenebilir?', 'Hiçbir C, B değildir', ['Bazı C\'ler B\'dir', 'Bütün C\'ler B\'dir', 'C ile B\'nin ilişkisi belirsizdir'], 'C, A\'nın içinde, A da B\'den ayrık olduğundan C de B\'den ayrıktır (Celarent kalıbı).'),
  ('\'Bazı öğrenciler sınavı geçemedi\' (O) önermesinin çevrilmişi (obversion) hangisidir?', 'Bazı öğrenciler sınavı geçemeyenlerdendir', ['Hiçbir öğrenci sınavı geçemeyenlerden değildir', 'Bütün öğrenciler sınavı geçti', 'Bazı sınavı geçenler öğrenci değildir'], 'O önermesi çevrilince niteliği olumlu olur ve yüklem olumsuzlanır: \'Bazı S, P-olmayandır\' (I).'),
  ('\'Hiçbir balina balık değildir\' önermesinin çevrilmişi hangisidir?', 'Bütün balinalar balık olmayanlardandır', ['Bazı balinalar balık olmayanlardan değildir, yani balıktırlar', 'Hiçbir balık balina değildir', 'Bütün balıklar balina olmayanlardandır'], 'E önermesi çevrilince A önermesine dönüşür: \'Bütün S, P-olmayandır\'.'),
  ('Dolaysız çıkarımlarda \'ters çevirme\' (kontrapozisyon) \'Bütün S, P\'dir\' önermesine uygulandığında hangi önerme elde edilir?', 'Bütün P olmayanlar S olmayandır', ['Bütün P\'ler S\'dir', 'Hiçbir S, P değildir', 'Bazı S\'ler P olmayanlardan değildir; yani kısmen P\'dir'], 'Kontrapozisyonda terimlerin yeri değişir ve ikisi de olumsuzlanır; A önermesinde bu işlem eşdeğer sonuç verir.'),
  ('Modern (Boole) yorumda tümel önermelerin konu terimi için hangi varsayım yapılmaz?', 'Konu teriminin kaplamında en az bir üye bulunduğu varsayımı', ['Terimin dağıtılabileceği varsayımı', 'Önermenin doğru ya da yanlış olabileceğini ileri süren bir varsayım yapılmaz', 'Terimin olumsuzunun alınabileceği varsayımı'], 'Boole yorumunda \'Bütün S P\'dir\' önermesi S boş olduğunda da doğrudur; geleneksel mantıktaki varoluşsal içerim kabul edilmez.'),
  ('\'Bütün unicornlar beyazdır\' önermesi Boole yorumuna göre unicorn bulunmadığı için nasıl değerlendirilir?', 'Boş doğru kabul edilir', ['Yanlıştır', 'Anlamsızdır', 'Doğruluk değeri yoktur, çünkü konu terimi boştur'], 'Boole yorumunda hiçbir unicorn yoksa \'beyaz olmayan unicorn bulunduğu\' doğru değildir; bu yüzden tümel olumlu önerme doğrudur.'),
  ('Üç kümenin (A, B, C) Venn diyagramında tüm bölgelerin kesişiminden oluşturulan kaç ayrı bölge (dışarıyla birlikte) vardır?', '8 bölge', ['6 bölge', '7 bölge', '9 bölge'], 'Üç küme için 2^3 = 8 bölge oluşur: yedi iç bölge ve dışarısı.'),
  ('\'Çalışırsan başarırsın. Başarırsan mutlu olursun. O hâlde çalışırsan mutlu olursun.\' akıl yürütmesinin kalıbı hangisidir?', 'Hipotetik (zincirleme şartlı) kıyas', ['Modus tollens, yani sonucu yadsıyarak öncülü yadsıma', 'Ayrık kıyas, yani seçeneklerden birini elemek', 'Yapıcı ikilem, yani iki seçenekten sonuç çıkarmak'], 'p → q ve q → r öncüllerinden p → r sonucu çıkarılır; bu kalıp hipotetik kıyas olarak bilinir.'),
  ('Aşağıdakilerden hangisi geçerli bir ayrık kıyas kalıbıdır?', 'p veya q; p değil; o hâlde q', ['p veya q; p doğru; o hâlde q kesinlikle yanlıştır', 'p veya q; o hâlde p', 'p veya q; q; o hâlde p'], 'Kapsayıcı veya\'da ancak bir seçeneğin yanlışlığı öteki seçeneğin doğruluğunu zorunlu kılar.'),
  ('\'Yağmur yağarsa ya yollar kapanır ya da maç ertelenir; yağmur yağdı\' önermelerinden hangisi zorunlu olarak çıkar?', 'Yollar kapandı ya da maç ertelendi', ['Yollar kapandı', 'Maç ertelendi', 'Hem yollar kapandı hem maç ertelendi'], 'Öncül onaylandığında yalnızca sonuçtaki ayrık önerme doğru olur; hangi seçeneğin gerçekleştiği bilinemez.'),
  ('\'Sorular zor olsa çoğu öğrenci kalır, sorular kolay olsa sınav ayırt edici olmaz. Sorular ya zor ya kolay olacak.\' sözlerinden hangisi çıkarılır?', 'Çoğu öğrenci kalacak ya da sınav ayırt edici olmayacak', ['Çoğu öğrenci kalacak, çünkü sorular zor olduğu için kesindir', 'Sınav ayırt edici olacak', 'Sorular ne zor ne kolay olacak'], 'Yapıcı ikilem: iki koşullu ve ayrık öncülden sonuçların ayrık biçimi çıkar.'),
  ('Bir ikilemi çürütmenin yollarından biri olarak \'ikilemin boynuzları arasından geçmek\' ne demektir?', 'Ayrık öncülün tam olmadığını, üçüncü bir seçenek bulunduğunu göstermek', ['Sonucun mantıksal olarak geçerli olduğunu kabul etmek', 'İkilemi olduğu gibi tekrarlamak', 'Öncülleri bir çelişmeye çevirmek'], 'Ayrık öncülün tam olmadığını (üçüncü bir seçenek bulunduğunu) göstermek, ikilemi çürütmenin klasik yoludur.'),
  ('\'Yangın çıkarsa alarm çalar. Alarm çaldı.\' bilgilerinden yangın çıktığı sonucuna varmak neden hatalıdır?', 'Alarm başka nedenlerle de çalabilir', ['Alarm hiçbir zaman yangınla ilişkili değildir', 'Koşullu önerme zaten yanlıştır', 'Alarm çalarsa yangın çıkmıştır diye zaten kabul edilmiştir'], 'Sonucu onaylama (affirming the consequent) biçimsel bir safsatadır: çıkarım yönü öncülden sonuca doğrudur.'),
  ('\'Bir sayı 4\'e bölünüyorsa 2\'ye bölünür. Bu sayı 4\'e bölünmüyor.\' bilgisinden sayının 2\'ye bölünmediği sonucuna varılırsa hangi hata yapılmış olur?', 'Öncülü yadsıma', ['Sonucu onaylama', 'Dört terim hatası', 'Kıyas zincirini kırma'], 'Öncülü yadsımak sonucu yadsımayı gerektirmez: 6, 4\'e bölünmese de 2\'ye bölünür.'),
  ('\'Eğer kitap ilginçse okurum\' önermesine göre \'kitabı okumadım\' bilgisinden ne çıkarılır?', 'Kitap ilginç değildi', ['Kitap ilginçti', 'Kitabın ilginç olup olmadığı belirsizdir', 'Kitap sıkıcı olduğundan okunmadı diye kesin söylenebilir'], 'Modus tollens: sonuç yadsınınca öncül de yadsınır; okumadıysam kitap ilginç değildir.'),
  ('\'Tüm mevsimlerde okula gidersem sınıfı geçerim\' ifadesinde kıyas geçerli olsun diye hangi öncül eklenmelidir?', 'Tüm mevsimlerde okula gittim', ['Sınıfı geçtim', 'Sınıfı geçmedim bu yüzden okula gitmedim', 'Bazı mevsimlerde okula gittim'], 'Modus ponens için öncülün (okula gitmek) onaylanması gerekir; sonucun onayı geçerli bir çıkarım vermez.'),
  ('\'Doğruluk tablosu\' yöntemiyle bir şartlı kıyasın geçersizliği nasıl gösterilir?', 'Öncüllerin doğru, sonucun yanlış olduğu bir satır bulunarak', ['Öncüllerin yanlış, sonucun doğru olduğu bir satır bulunarak', 'Öncüllerin ve sonucun doğru olduğu bir satır bularak', 'Sonucun totoloji olduğunu göstererek'], 'Öncüller doğruyken sonucun yanlış olabildiği tek bir satır bile kalıbın geçersizliğini kanıtlar (karşı örnek).'),
  ('Bir şartlı önermede \'ancak ve ancak\' kullanıldığında (çift şartlılık) hangi çıkarımlar geçerli olur?', 'Hem onaylama hem yadsıma çıkarımları iki yönde de geçerlidir', ['Yalnız öncülün onayından sonucun onayı', 'Yalnız sonucun yadsınmasından öncülün yadsınması', 'Hiçbir çıkarım geçerli olmaz'], 'Çift koşulluda iki yönde de koşullu geçerli olduğundan hem onaylama hem yadsıma çıkarımları iki yönlü kurulabilir.'),
  ('\'Yeterince çalışmayan kalır. Ali yeterince çalıştı.\' bilgilerinden \'Ali kalmaz\' sonucuna varmak neden güvenli değildir?', 'Başka nedenlerle de kalınabilir', ['Ali\'nin çalışması ölçülemez', 'Kıyas modus ponens\'e uyar', 'Çünkü \'kalır\' yüklemi anlamsızdır'], '\'Çalışmayan kalır\' koşulu çalışanın geçeceğini söylemez; öncülü yadsımak sonucu yadsımayı gerektirmez.'),
  ('\'Plan işe yararsa kazanırız. Plan işe yaramazsa ders çıkarırız. Plan ya işe yarar ya yaramaz.\' Bu öncüllerden ne çıkar?', 'Ya kazanırız ya da ders çıkarırız', ['Plan işe yarayıp yaramadığına bakılmaksızın kesinlikle kazanırız', 'Kesinlikle ders çıkarırız', 'Hem kazanırız hem ders çıkarırız'], 'Yapıcı ikilem: her iki seçenek de olumlu sonuç verir, ancak hangisinin gerçekleşeceği bilinemez.'),
  ('Düğünden sonra hastalanan altı konuğun yalnızca ortak yediği yemeğin tavuk salata olduğu saptanıyor ve hastalık nedeni olarak bu yemek gösteriliyor. Bu akıl yürütme Mill\'in hangi yöntemine dayanır?', 'Uyuşum yöntemi', ['Mill\'in ayrılık yöntemi, yani iki durum arasındaki tek fark', 'Birlikte değişim yöntemi', 'Artık (kalıntı) yöntemi'], 'Olayın görüldüğü bütün durumlarda ortak olan tek etken bulunduğundan, neden o etken sayılıyor; bu uyuşum yöntemidir.'),
  ('İki özdeş fidenin biri ışık alan, öbürü karanlık bir odaya konup yalnızca ışık dışındaki tüm koşullar eşit tutuluyor. Karanlıktaki fide solarsa solmanın nedeni ışıksızlıktır deniyor. Bu hangi yöntemdir?', 'Ayrılık (fark) yöntemi', ['Uyuşum yöntemi', 'Artık yöntemi', 'Birleşik analoji yöntemi'], 'Olayın görüldüğü ve görülmediği iki durum arasında tek fark varsa o fark neden sayılır; bu fark yöntemidir (kontrollü deney mantığı).'),
  ('Bir gazın sıcaklığı arttıkça basıncın da düzenli biçimde arttığını görüp ikisi arasında nedensel bir bağ olduğunu söylemek Mill\'in hangi yöntemini kullanır?', 'Birlikte değişim yöntemi', ['Mill\'in ayrılık yöntemi, yani farkın nedeni göstermesi', 'Uyuşum yöntemi', 'Artık yöntemi'], 'Bir olgudaki değişimin başka bir olgudaki değişimle sürekli birlikte gerçekleşmesi nedensel ilişkiye işaret eder.'),
  ('Bilimsel tümevarımla basit sayıma dayalı tümevarım arasındaki en önemli fark nedir?', 'Birincisi nedensel bağı araştırır', ['Bilimsel tümevarım kesin sonuç verir, sayım zayıf sonuç verir', 'Sayım tümdengelimin bir türüdür', 'Bilimsel tümevarım yalnız tek bir örneğe dayanır'], 'Basit sayımda yalnız tekrarlanma sayılır; bilimsel tümevarım nedeni araştırarak genelleme yapar. Her ikisi de olası sonuç verir.'),
  ('Yalnızca bir kentte yapılan ankete dayanarak \'bütün ülke halkı bu görüştedir\' demek tümevarım açısından hangi yanlışa yol açar?', 'Örneklem yetersiz', ['Tümdengelim hatası olur', 'Tam tümevarım sayılır', 'Kıyasta dört terim hatası olur'], 'Genelleme, evreni temsil edecek geniş ve çeşitli örneklemle güçlenir; küçük ve çarpık örnekten genelleme zayıf kalır.'),
  ('\'Bütün zümrütler yeşildir\' genellemesine ve \'yeşilmavi\' gibi yapay bir yüklemle Goodman\'ın ileri sürdüğü sorun neyi gösterir?', 'Aynı veri çelişen genellemeleri destekler', ['Tümdengelimin her zaman kesin olduğunu ve yanılmayacağını', 'Analojinin her koşulda geçerli bir çıkarım verdiğini', 'Tanımın döngüsel olmasının kaçınılmaz olduğunu'], 'Goodman\'ın \'grue\' örneği, aynı gözlem verisinin farklı yüklemlerle çelişen genellemelere uygun düşebildiğini gösterir (yeni tümevarım bilmecesi).'),
  ('Zayıf bir analojiye en iyi örnek hangisidir?', 'Ay\'da toprak ve kaya var, Dünya\'da da var; o hâlde Ay\'da da yaşam vardır', ['Bu öğrencinin iki arkadaşı da yüzücü; o hâlde okul yüzme takımına girebilir', 'İki aynı model telefonun biri ısındıysa öbürünün de ısınabileceğini düşünmek', 'İki aynı ilaç hapının ikisinde de aynı madde olduğunu belirlemek'], 'Toprak ve kaya benzerliği yaşamın varlığıyla ilgisizdir; analojinin gücü benzerliklerin sonuçla ilgisine bağlıdır.'),
  ('\'Kuş ve yarasa uçar, kuşlar yumurtlar; o hâlde yarasalar da yumurtlar\' akıl yürütmesinde analoji neden başarısız olur?', 'Yarasalar memelidir', ['Kuşlar uçmaz', 'Kuş ve yarasa aynı canlı türüdür', 'Yumurtlama uçmakla zaten aynı özelliktir'], 'Uçabilme benzerliği üremeyi belirlemez; yarasa memeli olduğundan yavru doğurur.'),
  ('Aşağıdakilerden hangisi tümdengelim argümanı değildir?', 'Son beş yıldır bu otobüs hep 08.10\'da geldi; yarın da 08.10\'da gelecek', ['Bütün insanlar ölümlüdür; Sokrates insandır; Sokrates ölümlüdür', 'Bütün eşkenar üçgenlerin açıları 60°\'dir; bu üçgen eşkenardır; açıları 60°\'dir', 'Ya ders ya oyun; ders yok; oyun var'], 'İlk seçenek geçmiş gözlemden gelecek için olası bir sonuç çıkarır; zorunluluk içermediğinden tümevarımdır.'),
  ('Bir yağmur dansından sonra yağmur yağmasına bakarak dansın yağmuru getirdiğini söylemek, tümevarımın hangi sorunuyla bağlantılıdır?', 'Ardışıklığı nedensellik sayma', ['Bütün örneklerin sayılamamasından doğan eksik tümevarım sorunu', 'Kıyasın üç yerine dört terim içermesinden doğan sorun', 'Tanımlananın tanımda yinelenmesinden doğan döngüsellik sorunu'], 'Birbirini izleyen olaylar arasında nedensel bağ kurmak için kontrollü karşılaştırma gerekir; ardışıklık tek başına yeterli değildir.'),
  ('\'Artık ödevlerini kopyalamayı bıraktın mı?\' sorusu, evet ya da hayır yanıtlansa da kişiyi aynı suçu kabul etmiş duruma sokar. Bu soru hangi safsataya örnektir?', 'Karmaşık (yüklü) soru', ['Yanlış neden', 'Bilgisizliğe başvurma', 'Birleştirme'], 'Soru, tartışmalı bir varsayımı (ödevleri kopyalıyordu) önceden doğru kabul ettiğinden hangi yanıt verilirse verilsin suçlama kabul edilmiş olur.'),
  ('\'Bu teori Nazi Almanyası\'nda ortaya çıktığı için yanlıştır\' savı hangi mantık yanlışına örnektir?', 'Köken safsatası', ['Çoğunluğa başvurma', 'Kaygan zemin', 'Bölme safsatası'], 'Bir görüşün doğruluğu kaynağına ya da çıkış koşullarına bakılarak değil, içeriğine ve kanıtına bakılarak değerlendirilmelidir.'),
  ('Bir araştırmacı, varsayımını destekleyen on çalışmayı sunup onu çürüten otuz çalışmayı hiç anmıyor. Bu hata hangisidir?', 'Seçici kanıt kullanma', ['Konu saptırma', 'Sonucu onaylama', 'İkna edici tanım'], 'Yalnızca işine gelen kanıtları göstermek, tablonun bütününü çarpıtır.'),
  ('A: \'Dünya yuvarlaktır.\' B: \'Hayır, düzdür.\' C: \'O hâlde doğru, dünyanın yarı yuvarlak olduğudur.\' C\'nin sonucu hangi yanlışa düşer?', 'Ortayı bulma safsatası', ['Geleneğe başvurma', 'Çoğunluğa başvurma', 'Kişiye saldırı'], 'İki görüş arasındaki orta nokta, ikisinden biri kanıtla yanlış çıkıyorsa doğru olmak zorunda değildir.'),
  ('\'Hayaletlerin olduğunu iddia ediyorsun; onların olmadığını sen kanıtla\' diyen kişi hangi hatayı yapar?', 'İspat yükünü karşı tarafa yıkma', ['Döngüsel kanıtlama', 'Yeniliğe başvurma', 'Birleştirme safsatası'], 'İddiayı ortaya atan kişi kanıt sunmakla yükümlüdür; kanıt yükünü karşı tarafa yüklemek mantıksal hatadır.'),
  ('Yaz aylarında hem dondurma satışları hem de boğulma vakaları artıyor. \'Dondurma yemek boğulmaya yol açar\' diyen kişi hangi hataya düşer?', 'Birlikte görülmeyi nedensellik saymak', ['Kumarbaz yanılgısı', 'Kaygan zemin', 'Korkuluk'], 'İki olgu ortak bir nedenden (sıcak hava) etkilenebilir; birlikte artmaları aralarında doğrudan neden-sonuç ilişkisi kanıtlamaz.'),
  ('\'Okul bir fabrikadır, öğrenciler ürün olduğuna göre başarı standart ölçütlerle denetlenmelidir\' sözündeki akıl yürütme neden zayıftır?', 'Yanlış analoji', ['Sonucu onaylama hatası içerir', 'Orta terim dağıtılmamıştır', 'Çelişik önermeler kullanır'], 'Eğitimin insanla ilgili özellikleri fabrika üretiminden önemli ölçüde ayrıdır; benzerlik sonuca yetecek ölçüde ilgili değildir.'),
  ('\'Bu sigortayı yaptırmazsan evin yanar, çocukların sokakta kalır\' diyen satıcı hangi safsatayı kullanır?', 'Korkuya başvurma', ['Bilgisizliğe başvurma', 'Köken safsatası', 'Eşseslilik'], 'Kanıt yerine abartılı korku duygusu uyandırarak ikna etmek, korkuya başvurmadır; açık bir güç tehdidi içermez.'),
  ('Satıcı müşteriye \'Siz zeki biri olarak bu teklifin kaçmayacak fırsat olduğunu hemen anlarsınız\' diyor. Bu söz hangi safsataya yaklaşır?', 'İltifata (dalkavukluğa) başvurma', ['Kişiye saldırı', 'Kaygan zemin', 'Saman adam'], 'Övgüyle karşıdakinin onayını kazanmaya çalışmak, argüman yerine kişinin kendini beğenmişliğini kullanır.'),
  ('\'Kurallar herkes için geçerlidir; ancak benim durumum özeldir, bu yüzden bu kuraldan muaf olmalıyım\' diyen kişi hangi hatayı yapar?', 'Özel ayrıcalık talebi', ['Ortayı bulma', 'Kumarbaz yanılgısı', 'Teksas keskin nişancısı'], 'Muafiyet için bağımsız, kabul edilebilir bir gerekçe göstermeden kuralın dışında tutulmayı istemek özel ayrıcalık safsatasıdır.'),
  ('Bir tartışmacı sözü almadan önce \'Karşıdaki, daha önce de yalan söyleyen biridir; ne derse desin inanmayın\' diyor. Bu hamle hangi safsatadır?', 'Kuyuyu zehirleme', ['Ortayı bulma', 'Teksas nişancısı', 'Yanlış analoji'], 'Karşı tarafın söyleyeceği şeylere önceden güvensizlik aşılayıp tartışmayı baştan baltalamak kuyuyu zehirlemedir.'),
  ('\'Kesmek suçtur; cerrah da hastayı keser; o hâlde cerrah suçludur\' akıl yürütmesi hangi safsatadır?', 'Kural istisnalarını yok sayma', ['Kumarbaz yanılgısı', 'Teksas nişancısı', 'Birleştirme'], 'Genel kural, uygulandığı koşulları (cerrahi müdahale gibi) hesaba katmadan istisnai duruma uygulanmıştır.'),
  ('Girit\'li Epimenides\'e atfedilen \'Bütün Giritliler yalancıdır\' sözünün yalancı paradoksunun bir biçimi olarak ele alınmasının nedeni nedir?', 'Kendine gönderme içermesi', ['Yalnızca bir kıyas hatası olması', 'Totoloji sayılabilecek bir önerme olması', 'Bir tanım biçiminde kurulmuş olması'], 'Konuşan da Giritli olduğundan sözün doğru olması onu yanlış, yanlış olması ise doğru kılar; döngüsel bir kendine gönderme vardır.'),
  ('Yalancı paradoksu için Tarski\'nin önerdiği çözümün özü nedir?', 'Nesne dil ile üst dili ayırmak', ['Yalancı cümleyi totoloji ilan edip mantık dışı bırakmak', 'Bütün önermelerin yalnızca tikel olabileceğini söylemek', 'Her cümleye üçüncü bir doğruluk değeri vermek'], 'Doğruluk yükleminin kendi dilinde tanımlanmasını yasaklayan basamaklı dil ayrımı, kendine gönderme döngüsünü kırar.'),
  ('Hilbert\'in sonsuz oteli düşünce deneyi sonsuz kümeler hakkında hangi gerçeği örnekler?', 'Sonsuz bir kümenin öz alt kümesiyle bütün kadar elemanlı olabileceğini', ['Her kümenin sonlu olduğunu', 'Boş kümenin her kümenin elemanı olduğunu', 'Alt kümenin bütünden her zaman az elemanlı olduğunu'], 'Dolu otelde yeni gelene yer açmak için herkesi bir oda kaydırmak mümkündür; sonsuzda bütün ile parça eşit büyüklükte olabilir.'),
  ('Lewis Carroll\'ın \'Kaplumbağa Akhilleus\'a Ne Dedi\' diyalogu mantık kuralları hakkında hangi noktayı vurgular?', 'Çıkarım kuralının yeni bir öncül olarak eklenemeyeceğini', ['Her kıyasın dört terimli olduğunu', 'Bütün önermelerin totoloji olduğunu', 'Çelişik öncüllerden her şeyin çıkmadığını'], 'Kuralı yeni bir öncül gibi yazmak yeni bir kural gerektirir; böylece kuralın uygulanması öncüllerle ifade edilemez.'),
  ('Kurt Gödel\'in 1931\'de yayımladığı eksiklik teoremleri hangi sonuca ulaşır?', 'Yeterince güçlü tutarlı sistemlerde kanıtlanamayan doğru önermeler vardır', ['Bütün matematiksel önermelerin kanıtlanabilir olması', 'Mantığın çelişik olması', 'Kıyasın geçerli olmaması'], 'Aritmetiği içeren tutarlı her biçimsel sistemde, sistem içinde ne kanıtlanabilen ne çürütülebilen önermeler vardır.'),
  ('Bir termostatın \'oda biraz serinse ısıtıcıyı biraz güçlendir\' türü kurallarla çalışması hangi mantık anlayışına dayanır?', 'Bulanık mantık', ['Kıyas mantığı', 'Sorites paradoksu', 'Ad hoc tanım'], 'Dereceli ve sözel değerlere dayanan denetim kuralları, bulanık mantığın en yaygın uygulama alanıdır.'),
  ('Özdeşlik ilkesinin (\'A, A\'dır\') mantıksal çıkarımdaki başlıca işlevi nedir?', 'Terimin anlamını sabit tutmak', ['Her önermeyi tümel biçime sokup dağıtılmış kılmak', 'Öncül sayısını ikiyle sınırlayıp sonucu zorunlu kılmak', 'Çelişkileri doğru sayıp kıyas dışına çıkarmak'], 'Terim kıyas içinde anlam değiştirirse (dört terim) akıl yürütme bozulur; özdeşlik ilkesi anlamın sabit kalmasını gerektirir.'),
  ('\'Bazı öğrenciler başarılıdır\' önermesinin niceleme mantığındaki doğru gösterimi hangisidir? (Ö: öğrenci, B: başarılı)', '∃x (Ö(x) ∧ B(x))', ['∃x (Ö(x) → B(x))', '∀x (Ö(x) ∧ B(x))', '∀x (Ö(x) → B(x))'], 'Varlık niceleyiciyle ve bağlacı kullanılır; koşullu bağlaç yalnız bütün için uygun, varlık için yanıltıcıdır.'),
  ('\'Hiçbir öğrenci çalışkan değildir\' önermesi (Ö, Ç) niceleme mantığında nasıl yazılır?', '¬∃x (Ö(x) ∧ Ç(x))', ['∃x (Ö(x) ∧ ¬Ç(x))', '¬∀x (Ö(x) → Ç(x))', '∀x (Ö(x) ∧ ¬Ç(x))'], 'Hem öğrenci hem çalışkan olan hiçbir x yoktur; bu ∀x (Ö(x) → ¬Ç(x)) ile de eşdeğerdir.'),
  ('Evren tam sayılar kümesi olduğunda \'∃x (x · x = 2)\' önermesi için hangisi doğrudur?', 'Yanlıştır', ['Doğrudur', 'Belirsizdir', 'Totolojidir'], 'Karesi 2 olan tam sayı yoktur (√2 irrasyoneldir); aynı önerme gerçek sayılar evreninde doğru olurdu.'),
  ('\'Yarın yağmur yağması olanaklıdır ama zorunlu değildir\' önermesinde yağmurun yağması hangi kipte düşünülmüştür?', 'Olumsal', ['Zorunlu', 'Olanaksız', 'Tümel'], 'Hem gerçekleşmesi hem gerçekleşmemesi olanaklı olan duruma olumsal denir.'),
  ('Aristoteles\'in \'Yorum Üzerine\' adlı eserinde tartıştığı \'yarın deniz savaşı olacak\' örneği hangi probleme dikkat çeker?', 'Gelecekteki olumsal önermelerin şimdiki doğruluğu', ['Kıyasın dört ayrı şekil taşıması ve bunların sayısı', 'Tanımın döngüsel olabilmesi ve bunun sakıncası', 'Önermelerin her zaman totoloji olması durumu'], 'Gelecek olumsal önermelere şimdiden kesin doğruluk değeri vermek kadercilik doğurur; bu üç değerli mantıkların da bir motivasyonudur.'),
  ('Saul Kripke\'nin 1960\'lardaki \'olanaklı dünyalar\' semantiği modal mantıkta neyi sağlamıştır?', 'Zorunluluğu erişilebilir dünyalarda doğruluk saymak', ['Doğruluk tablolarının ilk kez kullanılması ve yaygınlaşması', 'Kıyas şekillerinin sayısını dörde çıkarma yöntemi', 'Çelişmezlik ilkesinin kaldırılması ve çelişik önermelerin kabulü'], 'Kripke semantiğinde □p, p\'nin erişilebilir her olanaklı dünyada doğru olması; ◇p ise en az birinde doğru olmasıdır.'),
  ('\'Dört kenarlı bir üçgen vardır\' önermesi modal açıdan nasıl nitelenir?', 'Mantıksal olarak olanaksız', ['Olumsal, yani hem olabilir hem olmayabilir', 'Zorunlu, yani her koşulda doğrudur', 'Olanaklı ama olumsal, yani şans eseri doğru'], 'Üçgenin tanımı ile dört kenarlılık çelişir; bu yüzden önerme hiçbir olanaklı dünyada doğru olamaz.'),
  ('Bir kasabada sakinler ya her zaman gerçeği söyler ya da her zaman yalan söyler. Şebnem "Can yalancıdır" der; Can "biz farklı türdeniz" der. Bu iki söze göre hangi sonuç kesindir?', 'Yalnızca Can şövalyedir', ['İkisi de şövalyedir', 'Yalnızca Şebnem şövalyedir', 'İkisi de yalancıdır'], 'Dört olası durum sözlerle karşılaştırılınca yalnızca Can şövalye, Şebnem yalancı olduğunda her iki söz de türüne uygun olur.'),
  ('Şövalyeler daima doğruyu, yalancılar daima yanlışı söyler. İki yolcudan Ece "Mustafa yalancıdır", Mustafa "ikimiz de şövalyeyiz" diyor. Yolcuların türleri hakkında ne söylenebilir?', 'Yalnızca Ece şövalyedir', ['İkisi de şövalyedir', 'Yalnızca Mustafa şövalyedir', 'İkisi de yalancıdır'], 'Dört olası durum sözlerle karşılaştırılınca yalnızca Ece şövalye, Mustafa yalancı olduğunda her iki söz de türüne uygun olur.'),
  ('Şövalyeler daima doğruyu, yalancılar daima yanlışı söyler. İki yolcudan Ali "biz farklı türdeniz", Zeynep "ikimiz de yalancıyız" diyor. Yolcuların türleri hakkında ne söylenebilir?', 'Yalnızca Ali şövalyedir', ['İkisi de şövalyedir', 'Yalnızca Zeynep şövalyedir', 'İkisi de yalancıdır'], 'Dört olası durum sözlerle karşılaştırılınca yalnızca Ali şövalye, Zeynep yalancı olduğunda her iki söz de türüne uygun olur.'),
  ('Bir kasabada sakinler ya her zaman gerçeği söyler ya da her zaman yalan söyler. Gülşen "ikimiz de şövalyeyiz" der; Bora "Gülşen yalancıdır" der. Bu iki söze göre hangi sonuç kesindir?', 'Yalnızca Bora şövalyedir', ['İkisi de şövalyedir', 'Yalnızca Gülşen şövalyedir', 'İkisi de yalancıdır'], 'Dört olası durum sözlerle karşılaştırılınca yalnızca Bora şövalye, Gülşen yalancı olduğunda her iki söz de türüne uygun olur.'),
  ('Şövalyeler daima doğruyu, yalancılar daima yanlışı söyler. İki yolcudan Berkant "ikimiz de şövalyeyiz", Su "içimizden en az biri yalancıdır" diyor. Yolcuların türleri hakkında ne söylenebilir?', 'Yalnızca Su şövalyedir', ['İkisi de şövalyedir', 'Yalnızca Berkant şövalyedir', 'İkisi de yalancıdır'], 'Dört olası durum sözlerle karşılaştırılınca yalnızca Su şövalye, Berkant yalancı olduğunda her iki söz de türüne uygun olur.'),
  ('Bir adada herkes ya daima doğru söyleyen şövalyedir ya da daima yalan söyleyen yalancıdır. Adada tanıştığınız Orhan, "ikimiz de yalancıyız" diyor; Naz ise "ben şövalyeyim" diyor. Buna göre aşağıdakilerden hangisi doğrudur?', 'Yalnızca Naz şövalyedir', ['İkisi de şövalyedir', 'Yalnızca Orhan şövalyedir', 'İkisi de yalancıdır'], 'Dört olası durum sözlerle karşılaştırılınca yalnızca Naz şövalye, Orhan yalancı olduğunda her iki söz de türüne uygun olur.'),
  ('Bir kasabada sakinler ya her zaman gerçeği söyler ya da her zaman yalan söyler. Işıl "içimizden en az biri yalancıdır" der; Barış "Işıl yalancıdır" der. Bu iki söze göre hangi sonuç kesindir?', 'Yalnızca Işıl şövalyedir', ['İkisi de şövalyedir', 'Yalnızca Barış şövalyedir', 'İkisi de yalancıdır'], 'Dört olası durum sözlerle karşılaştırılınca yalnızca Işıl şövalye, Barış yalancı olduğunda her iki söz de türüne uygun olur.'),
  ('Müdür odasındaki vazo kırılınca dört öğrenci konuşuyor. Ali: \'Vazoyu ben kırmadım.\' Burcu: \'Vazoyu Ceyda kırdı.\' Ceyda: \'Vazoyu Deniz kırdı.\' Deniz: \'Vazoyu ben kırmadım.\' Yalnızca biri doğru söylediğine göre vazoyu kim kırmıştır?', 'Ali', ['Burcu', 'Ceyda', 'Deniz'], 'Her olası suçlu için doğru söyleyenleri sayınca yalnız Ali suçluyken tek kişi (Deniz) doğru söyler.'),
  ('A, B, C, D ve E bir koşuyu bitirmiştir. A, B\'den önce bitirmiş; C, A\'nın hemen ardından gelmiş; D sonuncu olmuş; E, A\'dan önce bitirmiş; B dördüncü olmuştur. Üçüncü sırayı kim almıştır?', 'C sporcusu', ['A sporcusu', 'E sporcusu', 'B sporcusu'], 'Sıralama E, A, C, B, D biçimindedir; bu sıra bütün koşulları sağlayan tek sıralamadır.'),
  ('Beş sporcu bir yarışa katılmış; C birinci, B ise D\'nin hemen arkasında; A, E\'den önce; E, D\'den önce bitirmiştir. Beşinci sırayı kim almıştır?', 'B sporcusu', ['A sporcusu', 'D sporcusu, çünkü B onun önündedir', 'E sporcusu'], 'Koşulları sağlayan tek sıra C, A, E, D, B olduğundan en sonda B yer alır.'),
  ('Dışarıdan ayırt edilemeyen 9 bilyeden biri diğerlerinden daha ağırdır. Kefeli bir teraziyle en az kaç tartımda ağır bilye kesin bulunur?', '2 tartım', ['3 tartım', '4 tartım', '1 tartım yeter'], 'Bilyeler 3\'lü üç gruba ayrılıp iki gruba tartılır; ağır grup belirlenince onun içinde bir tartımla ağır bilye bulunur.'),
  ('\'Camlar kırıldı çünkü top penceredeki camlara çarptı\' cümlesi neden bir argüman değil, açıklamadır?', 'Kırılma olgusu zaten bilinmekte', ['Cümlede hiç öncül bulunmamaktadır', 'Cümle bir soru biçimindedir', 'Cümle tümel olumsuz önermedir'], 'Açıklamada olgunun doğruluğu kabul edilir, neden aranır; argümanda ise bir sonucun doğruluğu öncüllerle gösterilmeye çalışılır.'),
  ('Geçersiz bir tümdengelim argümanının sonucu için hangisi söylenebilir?', 'Sonuç doğru olabilir ama zorunlu çıkmaz', ['Sonuç mutlaka yanlıştır, çünkü öncüller sonucu desteklemez', 'Sonuç mutlaka doğrudur, çünkü öncüller doğrudur', 'Sonuç anlamsızdır ve değerlendirilemez, çünkü argüman geçersizdir'], 'Geçersizlik sonucun yanlış olduğunu değil, öncüllerin sonucu garanti etmediğini gösterir.'),
  ('\'Ali öğrencidir; dolayısıyla müzeye indirimli girebilir\' argümanında eksik bırakılmış (gizli) öncül hangisidir?', 'Öğrenciler indirimden yararlanır', ['Ali müzeyi çok sever ve sık ziyaret eder', 'Müze bugün açık olup bilet satışı yapmaktadır', 'Ali bilet almış ve girişte göstermiştir'], 'Sonucun öncülden çıkması için gizli bir genel öncül gerekir; bu tür eksik kıyaslara entimem denir.'),
  ('Bir argümanı çürütmek için kullanılabilecek yöntemlerden biri hangisidir?', 'Öncül ya da çıkarım bağını çürütmek', ['Söyleyen kişiyi küçümsemek ve itibarsızlaştırmak', 'Aynı görüşü daha yüksek sesle yinelemek', 'Çoğunluğun farklı düşündüğünü hatırlatmak'], 'Meşru çürütme, öncülün doğruluğuna ya da çıkarım bağının gücüne itiraz eder; kişiyi hedef almak safsatadır.'),
  ('\'Gün boyunca sürekli yağmur yağdı\' ve \'Gün boyunca bir damla yağmur yağmadı\' önermeleri birlikte ele alındığında ne söylenebilir?', 'Birlikte doğru olamazlar', ['Birlikte doğru olabilirler', 'İkisi de her zaman doğrudur', 'İkisi de mantıksal olarak aynıdır'], 'İkisi birbirinin çelişiğine yakın bir ilişki taşır; aynı gün için ikisi de doğru olamaz.'),
  ('\'Bütün sebzeler sağlıklıdır; patates bir sebzedir; o hâlde patates sağlıklıdır\' argümanı geçerli kabul edilirse eleştirinin odağı nereye yönelmelidir?', 'Öncüllerin doğruluğuna', ['Kıyasın biçimine, çünkü Barbara geçersizdir', 'Argümanın uzunluğuna ve söylenişine', 'Sonucun cümle yapısına ve dilbilgisine'], 'Biçim geçerliyse (Barbara) tartışma öncüllerin doğruluğuna kayar; ilk öncül aşırı genelleme içeriyor olabilir.'),
  ('\'A fortiori\' (daha güçlü nedenle) akıl yürütmesine örnek hangisidir?', 'Çocuk yapabiliyorsa yetişkin de yapar', ['Sınavda herkes kopya çekiyor, ben de çekeyim', 'Her kuş uçar, o hâlde her uçan kuştur', 'Yağmur yağarsa yol ıslanır, yol ıslandı, yağmur yağdı'], 'Daha az olası durumda doğru olan, daha olası durumda daha da güçlü nedenle doğrudur.'),
  ('\'Ankara altı harflidir\' cümlesinde \'Ankara\' sözcüğünün yazıda tırnak içine alınmasını gerektiren mantıksal ayrım hangisidir?', 'Kullanım–anma ayrımı', ['Analitik–sentetik ayrımı', 'Tümel–tikel ayrımı', 'Doğru–geçerli ayrımı'], 'Sözcüğün kendisinden söz ederken (anma) sözcük şehri değil, harf dizisini gösterir; bu kullanım–anma ayrımıdır.'),
  ('\'Bu politika bir katliamdır\' yerine \'bu politika bazı kayıplara yol açtı\' demek hangi dil olgusuna örnektir?', 'Yüklü sözcükle tutum yönlendirme', ['Yapı kaynaklı bir tanım hatası olma durumu', 'Kıyasta orta terimin dağıtılmaması hatası', 'Üçüncü hâlin olmaması ilkesinin ihlali'], 'Aynı olay farklı yüklü sözcüklerle anlatıldığında dinleyicinin tutumu etkilenir; bu, tartışmada tarafsız dil kullanımını önemli kılar.'),
  ('\'Renksiz yeşil fikirler öfkeyle uyur\' cümlesi dilbilgisi kuralına uygun olmasına karşın neden anlam açısından sorunludur?', 'Terimlerin anlamlı önerme kurmaması', ['Cümlenin olumsuz biçimde kurulmuş olması', 'Cümlenin gereğinden uzun olması', 'Cümlenin tümel nitelik taşıması'], 'Chomsky\'nin bu örneği, sözdizimsel doğruluğun anlamlılığı garanti etmediğini gösterir.'),
  ('Yüklem \'zorunlu olarak doğru\' diye nitelenen bir önermenin (ör. \'Bekâr evlenmemiştir\') doğruluğu neye bağlıdır?', 'Terimlerin anlamına', ['Gözlem ve deneye, yani olguların sınanmasına', 'Çoğunluğun görüşüne, yani oy sayısına', 'Tarihsel olaylara, yani geçmişteki örneklere'], 'Terimlerin anlamından zorunlu çıkan önermelerin doğruluğu gözlemden bağımsızdır; bunlar analitik önermelerdir.'),
  ('Düşük prevalanslı bir hastalıkta pozitif test sonucunu \'hemen hemen kesin\' hastalık saymak, hangi hatanın örneğidir?', 'Temel oranı (yaygınlığı) göz ardı etme', ['Kumarbaz yanılgısı', 'Bölme safsatası', 'Hiçbir gerçek İskoç safsatası'], 'Testin doğruluğu kadar hastalığın ne kadar yaygın olduğu da pozitifin anlamını belirler.'),
  ('Çocuk doğumlarını izleyen küçük bir hastanede bir günde doğan çocukların yüzde 60\'ının erkek olması, büyük bir hastanede ise nadir görülür. Bu fark hangi ilkeyle açıklanır?', 'Küçük örneklemlerde sapmaların büyük olması', ['Kumarbaz yanılgısı', 'Simpson paradoksu', 'Boş doğruluk'], 'Örnek büyüdükçe oran gerçek orana yaklaşır; küçük örneklerde uç sonuçlar daha sık görülür.'),
  ('Kahve içenlerde kalp hastalığı oranının yüksek bulunduğu bir çalışmada çoğu kahve içicisinin aynı zamanda sigara içtiği anlaşılıyor. Bu durumda sigara hangi rolü oynar?', 'Karıştırıcı değişken', ['Bağımlı değişken, yani etkilenen sonuç değişkeni', 'Kontrol grubu, yani müdahale almayan karşılaştırma grubu', 'Örneklem, yani evreni temsil eden altküme'], 'Hem kahve içmeyi hem hastalığı etkileyen ortak etken, iki değişken arasındaki sahte ilişkiyi yaratabilir.'),
  ('Bir dergi \'Anketimize gönüllü katılanların yüzde 90\'ı görüşümüzü destekliyor, demek ki toplum büyük çoğunlukla bizimle\' diyor. Bu sonucun zayıflığı nedir?', 'Öz seçilim yanlılığı', ['Kıyasın şeklinin yanlış olması, yani orta terimin dağıtılmaması', 'Ortalamanın hesaplanırken aşırı derecede küçük çıkması', 'Bazı terimlerin hiç tanımlanmamış olması ve belirsizlik'], 'Görüşü güçlü olanlar ankete daha çok katılır; rastgele olmayan örnekleme evrene genellenemez.'),
  ('\'Hastalarımın hepsi bu bitki çayını içtikten sonra iyileşti\' diyen bir şifacıya karşı hangi kontrol eksikliği vurgulanmalıdır?', 'Karşılaştırma grubunun eksikliği', ['Çayın tadının ve kokusunun hastalara hoş gelip gelmediği', 'Hastaların yaşlarının birbirine ne kadar yakın olduğu', 'Çayın fiyatı ile bölgedeki diğer bitki çaylarının fiyat farkı'], 'Kendiliğinden iyileşen hastalıklarda iyileşme çaya değil zamana bağlı olabilir; ancak kontrol grubu karşılaştırması bunu ayırt eder.'),
  ('Yatırım şirketi \'Fonlarımızın son beş yıldaki ortalama getirisi yüzde 12\' diyor, ancak bu hesaba kapatılmış zayıf fonlar dahil değil. Bu durumda hangi çarpıtma vardır?', 'Hayatta kalanları sayma yanılgısı', ['Ekolojik yanılgı, yani topluluktan bireye geçiş', 'Kumarbaz yanılgısı', 'Savcı safsatası'], 'Yalnızca hayatta kalan fonlar sayıldığından ortalama olduğundan yüksek görünür.'),
  ('Hiçbir roman bilimsel makale değildir. Bütün dergi yazıları bilimsel makaledir. Bu öncüllerden hangisi kesinlikle çıkar?', 'Hiçbir dergi yazısı roman değildir', ['Bütün dergi yazıları romandır, çünkü ikisi de yazıdır', 'Bazı dergi yazıları romandır', 'Bütün romanlar dergi yazısıdır'], 'Orta terim (\'bilimsel makale\') iki öncülde de yüklem konumundadır; E ve A öncüllerinden E sonuç çıkar (Cesare).'),
  ('Bütün sanatçılar duyarlıdır. Hiçbir hesap makinesi duyarlı değildir. Bu öncüllerden hangisi zorunlu olarak çıkar?', 'Hiçbir hesap makinesi sanatçı değildir', ['Bazı hesap makineleri sanatçıdır', 'Bütün hesap makineleri sanatçıdır', 'Bütün sanatçılar hesap makinesidir, yani ikisi özdeştir'], 'Duyarlı olmayanlar sanatçı olamaz; orta terim yüklemde olan A–E öncülleri Camestres kipiyle E sonuç verir.'),
  ('Hiçbir böcek omurgalı değildir. Bazı canlılar omurgalıdır. Bu öncüllerden hangi sonuç kesindir?', 'Bazı canlılar böcek değildir', ['Hiçbir canlı böcek değildir, çünkü tümü omurgalıdır', 'Bütün canlılar böcektir', 'Bazı canlılar böcektir'], 'Omurgalı olan canlıların en az biri böcek olamayacağından bazı canlılar böcek değildir (Festino).'),
  ('Bütün kuşlar yumurtlar. Bazı hayvanlar yumurtlamaz. Bu öncüllerden hangisi çıkar?', 'Bazı hayvanlar kuş değildir', ['Bazı kuşlar hayvan değildir', 'Hiçbir hayvan kuş değildir, çünkü yumurtlamayan vardır', 'Bütün hayvanlar kuştur'], 'Yumurtlamayan bir hayvan kuş olamaz; A–O öncüllerinden O sonuç çıkar (Baroco).'),
  ('Bütün ressamlar yaratıcıdır. Bazı ressamlar yoksuldur. Bu öncüllerden hangisi zorunlu olarak çıkar?', 'Bazı yoksullar yaratıcıdır', ['Bütün yoksullar yaratıcıdır', 'Hiçbir yoksul yaratıcı değildir', 'Bütün yaratıcılar yoksuldur'], 'Hem yoksul hem ressam olan biri aynı zamanda yaratıcıdır; orta terim ressam iki öncülde de konudur (Datisi).'),
  ('Bazı öğrenciler başarılı değildir. Bütün öğrenciler gönüllüdür. Bu öncüllerden hangi sonuç çıkar?', 'Bazı gönüllüler başarılı değildir', ['Hiçbir gönüllü başarılı değildir, çünkü gönüllüler çalışmaz', 'Bazı gönüllüler başarılıdır', 'Bütün gönüllüler öğrencidir'], 'Başarısız bazı öğrencilerin hepsi gönüllü olduğundan bazı gönüllüler başarısızdır (Bocardo).'),
  ('Hiçbir doktor sigara satıcısı değildir. Bazı doktorlar yazardır. Bu öncüllerden hangisi kesinlikle çıkar?', 'Bazı yazarlar sigara satıcısı değildir', ['Hiçbir yazar sigara satıcısı değildir, çünkü yazarlar satış yapmaz', 'Bazı yazarlar sigara satıcısıdır', 'Bütün yazarlar doktordur'], 'Doktor olan yazarlar sigara satmaz; en az bir yazar sigara satıcısı değildir (Ferison).'),
  ('Bazı gazeteciler yabancı dil bilir. Bütün gazeteciler meraklıdır. Bu öncüllerden hangisi çıkar?', 'Bazı meraklılar yabancı dil bilir', ['Bütün meraklılar yabancı dil bilir', 'Hiçbir meraklı yabancı dil bilmez', 'Bütün yabancı dil bilenler gazetecidir'], 'Dil bilen bir gazeteci meraklı olduğundan en az bir meraklı dil bilir; tümel sonuç çıkmaz (Disamis).'),
  ('\'(p ∨ q) ∧ ¬r\' bileşik önermesinin doğruluk tablosunda kaç satır doğrudur?', '3 satır', ['2 satır, çünkü yalnız r yanlışken doğrudur', '4 satır, çünkü yarısı doğrudur', '5 satır, çünkü veya bağlacı genişlettir'], 'r yanlış olan 4 satırın üçünde p ya da q doğrudur; r doğru olan satırlarda ifade yanlıştır.'),
  ('\'(p → q) ↔ (¬q → ¬p)\' bileşik önermesi hakkında hangisi söylenebilir?', 'Totolojidir', ['Çelişmedir, çünkü iki yan zıt yönlüdür', 'Olumsal önermedir, çünkü yalnız bazı satırlarda doğrudur', 'Önerme değildir, çünkü çift koşullu karmaşıktır'], 'Koşulluyla kontrapozitifi eşdeğer olduğundan çift koşullu her satırda doğrudur.'),
  ('\'(p ∨ q) ∧ ¬(p ∧ q)\' önermesi hangi bağlaçla aynı tabloyu verir?', 'Dışlayıcı veya', ['Çift koşullu (p ↔ q), çünkü iki yan benzer', 'NAND (p ↑ q), çünkü ve\'nin olumsuzunu içerir', 'Koşullu (p → q), çünkü veya içerir'], 'Birisi doğru ama ikisi birden doğru olmayan durumlar tam olarak farklı değerli satırlardır.'),
  ('\'p → (q → r)\' önermesi üç değişkenli doğruluk tablosunun kaç satırında yanlıştır?', 'Yalnız 1 satırda', ['2 satırda, çünkü iki koşullu iç içedir', '3 satırda, çünkü r yanlış olan satırlar', '4 satırda, çünkü p doğru olan satırlar'], 'Yalnızca p doğru, q doğru ve r yanlış iken ifade yanlıştır.'),
  ('Aşağıdaki iki ifadeden hangisi \'(p ∧ q) → r\' ile aynı doğruluk tablosuna sahiptir?', '¬p ∨ ¬q ∨ r', ['(¬p ∧ ¬q) ∨ r', 'p ∧ q ∧ ¬r', '(p ∨ q) → r'], 'Koşullu önerme ¬(öncül) ∨ sonuç biçimine çevrilir: ¬(p ∧ q) ∨ r = ¬p ∨ ¬q ∨ r.'),
  ('\'(p ∧ q) ∨ (p ∧ ¬q)\' önermesi hangisine sadeleşir?', 'p', ['q', 'p ∧ q', 'p ∨ q'], 'p ∧ (q ∨ ¬q) = p ∧ doğru = p; ortak çarpan paranteze alınır.'),
  ('\'Üç önermeden en az ikisi doğrudur\' ifadesinin sembolik karşılığı hangisidir?', '(p ∧ q) ∨ (p ∧ r) ∨', ['p ∧ q ∧ r', 'p ∨ q ∨ r', '(p ∨ q) ∧ r'], 'En az iki doğru demek, ikili çiftlerden en az birinin birlikte doğru olmasıdır.'),
  ('\'Bu ülkedeki bütün sorunların tek nedeni eğitim sistemidir\' diyen bir konuşmacı hangi akıl yürütme hatasına düşer?', 'Tek nedene indirgeme', ['Çoğunluğa başvurma', 'Kaygan zemin', 'Birleştirme'], 'Karmaşık olguları çok sayıda nedenin birlikte etkisi olarak değil, yalnız bir nedene bağlayarak açıklamak hatalıdır.'),
  ('\'Bu ilaç yüzde yüz güvenli değilse hiç kullanılmamalı; çünkü kusursuz olmayan çözüm çözüm değildir\' diyen biri hangi safsatayı yapar?', 'Mükemmeliyetçi safsata (nirvana safsatası)', ['Kuyuyu zehirleme (kaynağı itibarsızlaştırma)', 'Teksas nişancısı (sonradan hedef çizme)', 'Kırmızı ringa (konuyu saptırma)'], 'Çözüm mükemmel olmadığı için reddedilirse mevcut çözümün olası yararları göz ardı edilir; gerçekçi karşılaştırma yapılmaz.'),
  ('\'Evrim nasıl mümkün olabilir, hayal bile edemiyorum; o hâlde yanlıştır\' sözündeki akıl yürütme hatası nedir?', 'Kişisel inanamamaya dayanma', ['Hiçbir gerçek İskoç', 'Yanlış analoji', 'Vurgu safsatası'], 'Bir şeyi anlayamamak ya da düşünememek onun yanlış olduğunu göstermez; kişinin sınırı kanıt yerine geçemez.'),
  ('Bir yönetici fazla mesai şikayetine \'Dünyada işsiz olanlar var, şikayet etmeye hakkın yok\' diyor. Bu söz hangi safsatadır?', 'Göreli yoksunluğa başvurma', ['Çağrışımla suçlama', 'Hasır altı etme', 'Özel ayrıcalık talebi'], 'Daha kötü bir durumun var olması mevcut sorunu geçersiz kılmaz; şikayetin içeriği ele alınmamıştır.'),
  ('Bir reklam \'Uzmanlar uyarıyor: bu yöntemi kullanmayanlar kaybedecek\' diyor, ama kimin hangi alanda uzman olduğunu belirtmiyor. Bu uygulama hangi hatayı gösterir?', 'Adı belirsiz otoriteye başvurma', ['Ortayı bulma', 'Kumarbaz yanılgısı', 'Savcı safsatası'], 'Kaynağı doğrulanamayan \'uzmanlar\' söylemi, kanıt göstermeden saygınlığı ödünç alır.'),
  ('\'Biri bu yağın kanser yaptığını söylüyor, diğeri yapmadığını; o halde yarı yarıya kanser yapar\' sözü hangi hatayı gösterir?', 'Ortayı bulma', ['Çağrışımla suçlama', 'Yaşatılanlara bakma', 'Köken safsatası'], 'İki karşıt iddianın ortası, kanıtla belirlenen gerçeğin yerini tutmaz.'),
  ('Bir kişi tartışmada kanıt göstermek yerine \'Bu açıkça doğru, kimse bunu inkâr edemez\' diyerek aynı iddiayı yineliyor. Bu hataya ne ad verilir?', 'Beyanla kanıtlama (ısrarla savunma)', ['Çoğunluğa başvurma (herkes böyle düşünüyor savı)', 'Yanlış neden (ardışıklığı nedensellik sanma)', 'Eşseslilik (anlam kayması)'], 'Gerekçe getirmeden bir iddiayı tekrar etmek ya da kesinmiş gibi göstermek ikna etmeyi yalnızca ısrara dayandırır.'),
  ('Bir kişi bir ilaç denemesi sonucunda \'Çalışmanın ilk yarısında etki yoktu; ikinci yarıda etki gördük, o hâlde ilaç etkilidir; ilk yarıyı göz ardı edebiliriz\' diyor. Bu uygulama hangi sorunla ilgilidir?', 'Verinin seçici kullanımı', ['Kıyasın biçimindeki dağılma hatası', 'Bir terimin iki anlamda kullanılması', 'Tanımın döngüsel olması'], 'Sonucu destekleyen kısmı alıp karşı veriyi dışarıda bırakmak seçici kanıt kullanımıdır.'),
  ('Russell\'ın \'Fransa\'nın şimdiki kralı kıldır\' cümlesini çözümlerken geliştirdiği betimlemeler kuramı neyi göstermeyi amaçlar?', 'Boş gönderimli cümlenin anlamsız değil yanlış olduğunu', ['Her cümlenin totoloji olduğunu', 'Kıyasın dört şekli olduğunu', 'Çelişkiden her şeyin çıktığını'], 'Cümle \'tam bir Fransa kralı vardır ve o kıldır\' biçiminde çözümlenir; bu birinci öğe yanlış olduğundan cümle yanlıştır.'),
  ('David Hilbert\'in 20. yüzyıl başında matematik için önerdiği programın amacı neydi?', 'Matematiği biçimsel temellendirme', ['Matematiği tümüyle ortadan kaldırmak', 'Sonsuz sayıları yasaklamak', 'Matematiği günlük dile çevirmek'], 'Hilbert programı, matematiğin sonlu yöntemlerle tutarlılığının kanıtlanmasını amaçladı; Gödel\'in teoremleri bu hedefi sarstı.'),
  ('Gödel\'in ikinci eksiklik teoremi biçimsel sistemlerin hangi sınırını gösterir?', 'Kendi tutarlılığını kanıtlayamama', ['Sistemin her önermeyi kanıtlayabileceğini', 'Sistemin çelişik olduğunu', 'Sistemin yalnız sonlu önermeler içerdiğini'], 'Aritmetiği içeren tutarlı bir sistem, kendi tutarlılığını sistem içinde kanıtlayamaz.'),
  ('Boole cebirinde \'x · x = x\' kuralı (idempotans) mantıksal olarak neyi anlatır?', 'Tekrar bilgi eklemez', ['Her önermenin yanlış olduğunu', 'Bir önermenin olumsuzunun kendisine eşit olduğunu', 'Veya bağlacının işlevsiz olduğunu'], 'p ∧ p ≡ p: tekrar sonucu değiştirmez; Boole\'un cebirsel sistemi sıradan cebirden bu kuralla ayrılır.'),
  ('\'Bütün kuşlar uçmaz\' cümlesi Türkçede neden mantıksal açıdan belirsizdir?', 'İki okunuşa açık olması', ['Öznesi olmadığı için', 'Yüklemi bulunmadığı için', 'Bileşik önerme olduğu için'], 'Olumsuzlama \'bütün\'ü mü yoksa yükleme mi kapsıyor, belli değildir; mantıkta bu yüzden E ya da O biçimine açıkça çevrilir.'),
  ('\'Ali ya sınavı geçer ya da kalır\' önermesi ile \'Ali ya çalışkandır ya da şanslıdır\' önermesi arasında mantıksal açıdan nasıl bir fark olabilir?', 'Birinde seçenekler dışlayıcıdır', ['İkisi de dışlayıcı veya içerir', 'İkisi de koşullu önermedir', 'Birincisi totoloji, ikincisi çelişmedir'], 'Geçme ve kalma birlikte doğru olamaz; çalışkan ve şanslı olmak ise birlikte mümkündür. Bu fark dışlayıcı ve kapsayıcı \'veya\' ayrımıdır.'),
  ('\'Bu odadaki bütün kitaplar okunmuştur\' önermesi ile \'Bu odada bulunan Ali okunmuş bir kitaptır\' ifadesi arasındaki fark nedir?', 'Birincisi tümel, ikincisi tekil önermedir', ['İkisi de tümel önermedir', 'Birincisi tikel, ikincisi tümeldir', 'İkisi de açık önermedir'], 'Tümel önerme bir sınıfın bütünü hakkında, tekil önerme belirli bir birey hakkında hüküm verir.'),
  ('\'Sıcaklık, oda termometresinin gösterdiği değerdir\' tanımı hangi tür tanımdır?', 'İşlemsel tanım', ['Kökensel tanım', 'Örnekle tanım', 'Olumsuz tanım'], 'İşlemsel tanım bir kavramı onu ölçmek ya da üretmek için yapılan işlemle tanımlar; bilimde ölçülebilirliği sağlar.'),
  ('Bir sözcüğü \'tür\' ve \'cins\' içinde yer vermeden yalnızca zıt anlamlısıyla açıklamak (\'sıcak, soğuk olmayandır\') hangi tanım kuralını bozar?', 'Tanım olumlu olmalıdır, olumsuzla ve zıtlıkla yapılmamalıdır', ['Tanım mecaz içermelidir', 'Tanım tanımlananı yinelemelidir', 'Tanım sınıfsız olmalıdır'], 'Olumsuz ve zıtlığa bağlı tanım, kavramın kendi içeriğini vermez; tanımlayan ifade tanımlanandan bağımsız bilgi içermelidir.'),
  ('Bilimde \'hipotez\', \'kuram\' ve \'yasa\' arasındaki en yaygın ayrım hangisidir?', 'Sınanmamış geçici açıklama', ['Yasa sınanmamış açıklamadır', 'Hipotez kesin kanıtlanmış bilgidir', 'Üçü de aynı şeydir'], 'Hipotez sınanabilir geçici bir açıklamadır; yasa gözlemlenen düzenliliği ifade eder; kuram yasaları açıklayan geniş bir çerçevedir.'),
  ('Bir araştırmacı \'Müzik dinleyen öğrenciler daha başarılıdır\' hipotezini sınarken müzik dinleyen ve dinlemeyen iki öğrenci grubunu başka koşullar eşit olacak biçimde karşılaştırıyor. Bu yaklaşım hangi yöntem düşüncesine dayanır?', 'Kontrollü deney', ['Tam sayım yöntemi', 'Çelişik alma', 'Dört terim hatası'], 'Yalnızca müzik değişkeni farklıysa başarı farkı ona bağlanabilir; bu Mill\'in fark yönteminin deneysel hâlidir.'),
  ('İki şey arasında benzerliğe dayanarak sonuç çıkaran analojide, benzerlik sayısı artarken sonucun güvenilirliği neye bağlı kalır?', 'İlgili benzerliklere', ['Benzerlik sayısının tek sayı olmasına', 'Sonucun kıyas biçimine sokulmasına', 'Karşılaştırılan nesnelerin büyüklüğüne'], 'Alakasız benzerlikler sayıca çok olsa da sonucu güçlendirmez; ilgililik belirleyicidir.'),
  ('\'Kanunda yazan yalnızca bu eylemdir, başka bir eylem yasak değildir\' çıkarımı, hukukta hangi yorum yöntemini temsil eder?', 'A contrario yorum', ['Evleviyet yorumu', 'Emsal yorum', 'Boşluk doldurma yorumu'], 'Bir kuralın yalnız belirtilen durumu kapsadığı, öteki durumları dışarıda bıraktığı sonucuna varmak a contrario yorumdur.'),
  ('\'Çimlere basmak yasaksa çiçekleri koparmak elbette yasaktır\' sonucu hukukta hangi yorumla ulaşılır?', 'A fortiori yorum', ['A contrario yorumu', 'Dar yorum', 'Tarihsel yorum'], 'Kuralın amacı çimleri korumaksa, daha fazla zarar veren eylem daha güçlü nedenle yasak sayılır.'),
  ('Bir tartışmada \'Kanıtlayamıyorsanız suçsuzdur\' ilkesi mantıksal açıdan hangi ispat yükü düzenlemesini yansıtır?', 'Suçlayanın kanıt yükü', ['Sanığın kendini kanıtlama yükünü', 'Hâkimin tarafsız kalma yükünü', 'Tanığın doğru söyleme yükünü'], 'İddiayı ortaya atan kişinin ispat yükü taşıması gerektiği ilkesi hem mantıkta hem hukukta kabul edilir.'),
  ('Üç arkadaştan her biri ya hep gerçeği ya da hep yalanı söylemektedir. Defne "aramızda en az bir şövalye vardır" diyor, Barış "üçümüz de yalancıyız" diyor, Yağmur ise "Defne şövalyeyse Barış yalancıdır" diyor. Bu durumda türleri için ne söylenebilir?', 'Defne ile Yağmur şövalyedir', ['Defne ile Barış şövalyedir, öteki yalancıdır', 'Üçü de yalancıdır', 'Yalnız Yağmur şövalyedir'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'defne ile yağmur şövalyedir, öteki yalancıdır\' durumu üç söz için de tutarlıdır.'),
  ('Bir kabilede şövalyeler yalnız doğru, yalancılar yalnız yanlış konuşur. Üç kabile üyesinden Tuna \'Selin ve Okan yalancıdır\', Selin \'Tuna ile Okan aynı türdendir\', Okan \'Tuna şövalyedir\' demiştir. Hangi yargı bu bilgilerle kesin olarak doğrudur?', 'Yalnız Selin şövalyedir', ['Tuna ile Okan şövalyedir, öteki yalancıdır', 'Üçü de yalancıdır', 'Tuna ile Selin şövalyedir, öteki yalancıdır'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'yalnız selin şövalyedir\' durumu üç söz için de tutarlıdır.'),
  ('Bir adada üç sakinle karşılaşırsınız; şövalyeler hep doğru, yalancılar hep yanlış söyler. Eren: "Nehir ya da Ozan şövalyedir." Nehir: "Eren şövalyedir." Ozan: "Eren yalancıdır." Bu söylemlere göre aşağıdakilerden hangisi doğrudur?', 'Eren ile Nehir şövalyedir', ['Yalnız Ozan şövalyedir', 'Eren ile Ozan şövalyedir, öteki yalancıdır', 'Üçü de şövalyedir'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'eren ile nehir şövalyedir, öteki yalancıdır\' durumu üç söz için de tutarlıdır.'),
  ('Bir bilmecede üç kişi konuşuyor ve her biri ya daima doğru ya daima yanlış söylüyor: Bahar → "Ulaş yalancıdır"; Ulaş → "üçümüz de yalancıyız"; Sinan → "Bahar şövalyedir". Çözüm aşağıdakilerden hangisidir?', 'Bahar ile Sinan şövalyedir', ['Yalnız Bahar şövalyedir', 'Üçü de şövalyedir', 'Yalnız Ulaş şövalyedir'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'bahar ile sinan şövalyedir, öteki yalancıdır\' durumu üç söz için de tutarlıdır.'),
  ('Üç arkadaştan her biri ya hep gerçeği ya da hep yalanı söylemektedir. Poyraz "Ilgın ile Emre aynı türdendir" diyor, Ilgın "aramızda tam iki yalancı vardır" diyor, Emre ise "üçümüz de yalancıyız" diyor. Bu durumda türleri için ne söylenebilir?', 'Yalnız Ilgın şövalyedir', ['Poyraz ile Emre şövalyedir, öteki yalancıdır', 'Yalnız Emre şövalyedir', 'Ilgın ile Emre şövalyedir, öteki yalancıdır'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'yalnız ilgın şövalyedir\' durumu üç söz için de tutarlıdır.'),
  ('Bir kabilede şövalyeler yalnız doğru, yalancılar yalnız yanlış konuşur. Üç kabile üyesinden Tarık \'aramızda tam iki yalancı vardır\', Elif \'Tarık ile Deniz farklı türdendir\', Deniz \'Tarık yalancıdır\' demiştir. Hangi yargı bu bilgilerle kesin olarak doğrudur?', 'Elif ile Deniz şövalyedir, öteki yalancıdır', ['Tarık ile Deniz şövalyedir, öteki yalancıdır', 'Yalnız Tarık şövalyedir', 'Yalnız Deniz şövalyedir'], 'Sekiz olası türler dağılımı sözlerle tek tek karşılaştırılınca yalnızca \'elif ile deniz şövalyedir, öteki yalancıdır\' durumu üç söz için de tutarlıdır.'),
  ('\'p → q\' koşullusunu kanıtlamak için \'q yanlışsa p yanlıştır\' önermesini göstermek hangi kanıt yöntemidir?', 'Kontrapozitif kanıt', ['Doğrudan kanıt', 'Matematiksel tümevarım', 'Örnekle kanıt'], 'p → q ile ¬q → ¬p eşdeğer olduğundan biri kanıtlanınca öbürü de kanıtlanmış olur.'),
  ('Bir genellemeyi çürütmek için tek bir örnek yeterli iken, kanıtlamak için hangisi yeterli değildir?', 'Birkaç örneğin bulunması', ['Çelişkiye ulaşılması', 'Aksiyomlardan türetilmesi', 'Evrensel bir akıl yürütme'], 'Örnekler genellemeyi destekler ama kanıtlamaz; kanıt, evrendeki bütün durumlar için geçerli bir akıl yürütmeyi gerektirir.'),
  ('Öklid\'in asal sayıların sonsuz olduğunu gösteren kanıtı hangi yöntemi kullanır?', 'Çelişki yoluyla kanıt', ['Tam sayım', 'Bilgisayarla tarama', 'Örneklerle genelleme'], 'Sonlu sayıda asal olduğu varsayılır; hepsinin çarpımına 1 eklenince listede olmayan bir asal bölen doğar ve çelişki ortaya çıkar.'),
  ('\'Bir şeyin var olduğunu göstermek için o şeyin örneğini inşa etmek\' hangi kanıt türüdür?', 'Yapıcı varlık kanıtı', ['Yapıcı olmayan (dolaylı) varlık kanıtı', 'Karşıt-evrik kanıt', 'Boş doğruluk'], 'Yapıcı kanıt ilgili nesneyi gösterir; yapıcı olmayan kanıt ise varlığını çelişki yoluyla gösterip örnek vermeyebilir.'),
  ('Bir argümanın kanıtlanmasında \'tümevarım basamağı\' (n için doğruysa n + 1 için doğrudur) neyi sağlar?', 'Doğruluğun aktarılmasını', ['Sonucun yanlışlığını', 'Önermenin sınırsız tekrarını', 'Aksiyomların çoğaltılmasını'], 'Taban adımıyla birlikte tümevarım adımı, özelliğin bütün doğal sayılara aktarıldığını gösterir.'),
  ('Bir önermenin hem kendisinin hem olumsuzunun doğruluğunu gösterebilen bir sistem için ne söylenebilir?', 'Tutarsızdır', ['Eksiksizdir', 'Yeterince güçlüdür ve mantıklıdır', 'Bilgi vermeyen ama tutarlı bir sistemdir'], 'Tutarsız sistemde her önerme kanıtlanabilir; böyle bir sistem gerçek bilgi ayırt edemez.'),
  ('p: \'Kapı açıktır\', q: \'Alarm çalar\'. \'Kapı açıksa alarm çalar, aksi hâlde çalmaz\' cümlesi hangi biçimdedir?', 'p ↔ q', ['p → q', '¬p → q', 'p ∧ q'], 'Açıkken çalıyor, açık değilken çalmıyor: alarm tam olarak kapı açıkken çalar.'),
  ('p: \'Adem sınava girdi\', q: \'Burcu sınava girdi\'. \'Adem ya da Burcu sınava girdi, ama ikisi birlikte girmedi\' cümlesi hangi bağlaçla gösterilir?', 'p ⊕ q', ['p ∨ q', 'p ∧ ¬q', 'p ↔ q'], 'Tam birinin girmesi, dışlayıcı veya demektir.'),
  ('\'Ne çay ne kahve içerim\' cümlesi (p: \'Çay içerim\', q: \'Kahve içerim\') için aşağıdakilerden hangisi eşdeğerdir?', '¬(p ∨ q)', ['¬(p ∧ q), yani biri yeter', '¬p ∨ ¬q', 'p ∧ ¬q'], 'Her ikisi de içilmiyorsa içilmeyenlerin birleşimi: ¬p ∧ ¬q = ¬(p ∨ q).'),
  ('\'Eğer yarın hava güzelse gezmeye çıkarız\' sözünün ardından hava güzel olmadığı hâlde gezmeye çıkıldığında söz yalan söylemiş sayılır mı?', 'Hayır; öncül yanlışken yanlış olmaz', ['Evet; söz tutulmamıştır', 'Evet; çünkü sonuç doğru olmuştur', 'Belirlenemez; çünkü koşullu önerme değildir'], 'Koşullu önerme yalnızca öncül doğru, sonuç yanlışken yanlıştır; hava güzel değilken söz çürütülmez.'),
  ('Bütün şairler duyarlıdır. Duyarlı olan herkes düşüncelidir. Düşünceli hiç kimse aceleci değildir. Bu üç öncülden hangisi kesinlikle çıkar?', 'Hiçbir şair aceleci değildir', ['Bazı şairler acelecidir', 'Bütün acelecilerin şair olduğu', 'Bütün şairler acelecidir'], 'Zincirleme kıyas: şair ⊂ duyarlı ⊂ düşünceli, ve düşünceliler aceleci olmadığından şairler de aceleci değildir.'),
  ('Bazı sporcular yazardır. Bütün yazarlar okurdur. Okur olan herkes meraklıdır. Hangi sonuç bu öncüllerden kesinlikle çıkar?', 'Bazı sporcular meraklıdır', ['Bütün sporcular meraklıdır', 'Hiçbir sporcu meraklı değildir', 'Bütün meraklılar sporcudur'], 'Sporcu ve yazar olan en az biri okur, dolayısıyla meraklıdır; tümel sonuç için tümel öncül gerekirdi.'),
  ('Bütün bahçıvanlar bitki sever. Bitki seven herkes sabırlıdır. Bazı çocuklar bahçıvandır. Bu öncüllerden hangisi kesinlikle çıkar?', 'Bazı çocuklar sabırlıdır', ['Bütün çocuklar sabırlıdır', 'Hiçbir çocuk bitki sevmez', 'Bütün sabırlılar çocuktur'], 'Bahçıvan olan çocuk bitki sever ve sabırlıdır; tümel sonuca ulaşılmaz.'),
  ('Hiçbir balina balık değildir. Bütün balıklar solungaçla solur. Bütün yunuslar balinadır. Hangi sonuç bu öncüllerden kesinlikle çıkar?', 'Hiçbir yunus balık değildir', ['Bütün yunuslar solungaçla solur', 'Bazı yunuslar balıktır', 'Hiçbir yunus solungaçla solumaz'], 'Yunus balinadır, balina da balık olmadığından yunus balık değildir; solungaç hakkında sonuç çıkmaz.'),
  ('Dolaptan bir kutu pasta kayboldu. Dört kardeşin sözleri: Aras: "Beril yaptı." Beril: "Cemil yaptı." Cemil: "Derya yapmadı." Derya: "Beril yalan söylüyor." Yalnızca bir kardeş doğru söylüyorsa pastayı kim yemiştir?', 'Derya (dördüncü kişi)', ['Aras (birinci kişi)', 'Beril (ikinci kişi)', 'Cemil (üçüncü kişi)'], 'Her olası sorumlu için sözlerin doğruluğu sayılınca yalnızca Derya sorumlu olduğunda doğru söyleyenlerin sayısı bir olur ve söyleyenlerin türleriyle çelişki doğmaz.'),
  ('Müzedeki bir vazonun kırılmasıyla ilgili dört görevli şunları söyledi: Aras: "Beril yapmadı." Beril: "Derya yapmadı." Cemil: "Beril yaptı." Derya: "Cemil doğru söylüyor." Doğru söyleyenlerin sayısı üç olduğuna göre sorumlu kimdir?', 'Beril (ikinci kişi)', ['Aras (birinci kişi)', 'Cemil (üçüncü kişi)', 'Derya (dördüncü kişi)'], 'Her olası sorumlu için sözlerin doğruluğu sayılınca yalnızca Beril sorumlu olduğunda doğru söyleyenlerin sayısı üç olur ve söyleyenlerin türleriyle çelişki doğmaz.'),
  ('\'Gülebilmek\' insan için hangi tümel türüdür?', 'Özgül özellik', ['Cins', 'Ayrım', 'Rastlantı'], 'Özgül özellik türün her üyesinde bulunur ve yalnız o türe aittir, ancak tanımın bir parçası olmaz.'),
  ('\'Saçının siyah olması\' bir insan için hangi tümel türüdür?', 'Rastlantısal özellik', ['Cins', 'Ayrım', 'Özgül özellik'], 'Bir insanda bulunup bulunmaması türün özünü değiştirmeyen niteliklere rastlantısal denir.'),
  ('\'Köpek\' terimi için en yakın cins aşağıdakilerden hangisidir?', 'Memeli', ['Canlı', 'Madde', 'Evcil olan'], 'En yakın cins, türü doğrudan kapsayan en dar sınıftır; köpek için bu memelidir.'),
  ('Bir tartışmada \'Bu işler böyle yürür, daha fazla sorgulamayın\' sözü hangi söylem hilesini temsil eder?', 'Düşünmeyi bitiren klişe', ['Dört terim hatası', 'Kendine gönderme', 'Dağılma, yani bütünün özelliğini parçaya yükleme'], 'Soruyu sorgulamaya kapatan kalıp söz, tartışmayı kanıt tartılmadan sonlandırır.'),
  ('Bir yorumcu, bir yazarın uzun metninden yalnızca bir cümleyi alıp \'Yazar bunu savunuyor\' diyor; oysa cümle yazarın eleştirdiği görüşü aktarıyor. Bu hata nedir?', 'Bağlamdan koparma', ['Kuyuyu zehirleme', 'Ortayı bulma', 'Yeniliğe başvurma'], 'Bir sözü geldiği bağlamdan ayırıp farklı anlam yüklemek, kaynağı çarpıtmak demektir.'),
  ('\'Hiçbir sürüngen memeli değildir; ...; o hâlde hiçbir timsah memeli değildir\' kıyasında boşluğa hangi öncül uygun düşer? (0: timsah, 1: sürüngen, 2: memeli)', 'Bütün timsahlar sürüngendir', ['Bazı timsahlar sürüngendir', 'Bütün sürüngenler timsahtır', 'Hiçbir timsah sürüngen değildir'], 'Tümel sonuç için küçük öncülün tümel olumlu olması gerekir (Celarent); tikel öncülle yalnız tikel sonuç çıkar.'),
  ('\'Bütün gazeteciler meraklıdır; ...; o hâlde bazı yazarlar meraklıdır\' kıyasında hangi öncül uygundur? (0: yazar, 1: gazeteci, 2: meraklı)', 'Bazı yazarlar gazetecidir', ['Bazı gazeteciler yazar değildir', 'Hiçbir yazar gazeteci değildir', 'Bazı meraklılar gazeteci değildir'], 'Yazar olan en az bir gazeteci meraklı olacağından bazı yazarlar meraklıdır (Darii).'),
  ('\'...; bütün balinalar memelidir; o hâlde bütün balinalar omurgalıdır\' kıyasını geçerli kılan öncül hangisidir? (0: balina, 1: memeli, 2: omurgalı)', 'Bütün memeliler omurgalıdır', ['Bazı memeliler omurgalıdır', 'Bütün omurgalılar memelidir', 'Bazı omurgalılar memeli değildir'], 'Orta terim (\'memeli\') büyük öncülde konu olarak dağıtılmalıdır; bu yalnızca tümel olumlu öncülle sağlanır (Barbara).'),
  ('\'Hiçbir bitki sinir sistemine sahip değildir; ...; o hâlde hiçbir ağaç sinir sistemine sahip değildir\' kıyasında hangi öncül gerekir? (0: ağaç, 1: bitki, 2: sinir sistemine sahip olan)', 'Bütün ağaçlar bitkidir', ['Bütün bitkiler ağaçtır', 'Bazı ağaçlar bitkidir', 'Hiçbir ağaç bitki değildir'], 'Tümel olumsuz büyük öncül ve tümel olumlu küçük öncülle Celarent kalıbı oluşur.'),
  ('Bir korsan sandığı, üç kutudan yalnız birinin içindedir. Kutuların üzerindeki yazılar şöyledir: 1. kutunun yazısı: \'Hazine burada.\' 2. kutunun yazısı: \'Hazine burada.\' 3. kutunun yazısı: \'Hazine 2. kutudadır.\' Yalnızca iki yazının doğru olduğu bilindiğine göre hazine hangi kutudadır?', 'İkinci kutu', ['Birinci kutu', 'Üçüncü kutu', 'Hiçbir kutuda değil, yazılar tutarsız'], 'Hazinenin üç olası yeri için doğru yazı sayısı hesaplanınca yalnızca ikinci kutu olduğunda doğru yazı sayısı iki olur.'),
  ('Bir kâşif, üç kapıdan yalnız birinin arkasındaki odada hazine olduğunu biliyor. Kapı yazıları: 1. kutunun yazısı: \'Hazine 3. kutuda değildir.\' 2. kutunun yazısı: \'Hazine 1. kutudadır.\' 3. kutunun yazısı: \'Hazine burada değil.\' Bu yazılardan tam iki tanesi doğru olduğuna göre hazine hangi kapının arkasındadır?', 'İkinci kutu', ['Birinci kutu', 'Üçüncü kutu', 'Hiçbir kutuda değil, yazılar tutarsız'], 'Hazinenin üç olası yeri için doğru yazı sayısı hesaplanınca yalnızca ikinci kutu olduğunda doğru yazı sayısı iki olur.'),
  ('Zenon\'un \'stadyum\' argümanı hangi iddiayı hedef alır?', 'Zamanın ayrık birimlerden oluşması', ['Tüm cisimlerin aynı hızda hareket ettiğini', 'Işığın hızının sonsuz olduğunu', 'Matematiğin sonsuz oluşunu'], 'Karşılıklı hareket eden cisimler karşısında aynı mesafenin farklı sürelerde katedilmesi, ayrık zaman varsayımını çelişkiye sokar.'),
  ('Evren doğal sayılar kümesi (0 dahil) iken \'∃x ∀y (x ≤ y)\' önermesi için hangisi doğrudur?', 'Doğrudur; x = 0 her y için sağlar', ['Yanlıştır; en küçük sayı yoktur', 'Evren sonlu olmadığı için belirsizdir', 'Önerme değildir'], '0, bütün doğal sayılardan küçük ya da eşit olduğundan tikel-evrensel iç içe niceleme doğrudur.'),
  ('Evren doğal sayılar iken \'∃x ∀y (y > x)\' önermesi için ne söylenebilir?', 'Yanlıştır', ['Doğrudur; x = 0 yeter', 'Doğrudur; x = 1 yeter', 'Evrene bağlı değildir'], 'x\'in kendisi de y olabileceğinden y > x koşulu her y için sağlanamaz; hiçbir x bu koşulu sağlamaz.'),
  ('Evren sonlu ve {1, 2, 3} olduğunda \'∀x ∃y (y > x)\' önermesi neden yanlıştır?', '3\'ten büyük sayı bulunmaz', ['1 için büyük bir sayı olmadığı için', 'Evren sonlu olduğu için önerme tanımsızdır', 'Önerme her zaman yanlıştır'], 'Evrenin en büyük elemanı için koşulu sağlayan y yoktur; niceleme evrene bağımlıdır.'),
  ('Beş arkadaş bir tiyatro sırasında yan yana oturuyor. Ceren en soldadır; Deniz en sağdadır; Ali ile Bora yan yana oturur ve Bora, Ali\'nin solundadır; Ece ile Ali arasında en az bir kişi vardır. Soldan üçüncü koltukta kim oturur?', 'Bora', ['Ece', 'Ali', 'Deniz'], 'Ceren ilk, Deniz son olduğundan orta üç koltuğa Ece, Bora, Ali yerleşir; Ece Ali\'den uzak olmalı ve Bora Ali\'nin solunda yan yanadır: Ceren, Ece, Bora, Ali, Deniz.'),
  ('Beş kişi bir sinema kuyruğunda bekliyor. Ece sonuncudur; Ali, Bora\'dan öndedir; Ali ile Deniz ardışıktır ve Deniz, Ali\'nin hemen arkasındadır; Ceren, Bora\'nın hemen arkasında bekler. Kuyrukta ikinci sırada kim vardır?', 'Deniz', ['Ali, çünkü sırada öndedir', 'Bora, çünkü Ceren onun arkasında', 'Ceren, çünkü sıra sonlara yakın'], 'Ali, Deniz, Bora, Ceren, Ece sırası bütün koşulları sağlayan tek sıradır.'),
  ('Bir duvar saati 5 vuruş yaptığında bu işlem 8 saniye sürüyor (ilk vuruştan sonuncuya kadar). Aynı saat 10 vuruş yapsaydı kaç saniye sürerdi?', '18 saniye', ['16 saniye sürerdi', '20 saniye sürerdi', '10 saniye sürerdi'], '5 vuruşta 4 aralık vardır; her aralık 2 saniyedir. 10 vuruşta 9 aralık = 18 saniye.'),
  ('\'Hava hem sıcak hem nemlidir\' ile \'Hava ne sıcaktır ne de nemlidir\' önermeleri arasındaki mantıksal ilişki nedir?', 'Birlikte doğru olamazlar ama birlikte yanlış olabilirler', ['Biri doğruysa öteki kesinlikle yanlış, biri yanlışsa öteki kesinlikle doğrudur', 'Birlikte yanlış olamazlar ama birlikte doğru olabilirler', 'Mantıksal olarak eşdeğerdirler'], 'Hava sıcak ama kuru olabilir; bu durumda ikisi de yanlıştır. İkisi birlikte doğru olamaz; ilişki karşıtlıktır.'),
  ('\'Ali ya da Veli yarışmayı kazandı\' önermesi ile \'Ali yarışmayı kazandı\' önermesi arasında hangi gerektirme ilişkisi vardır?', 'İkincisi birincisini gerektirir', ['Birincisi ikincisini gerektirir, tersi gerekmez', 'İkisi birbirini gerektirir', 'İkisi birbirinden bağımsızdır'], 'Ali kazandıysa \'Ali ya da Veli\' doğrudur; ama Veli kazandıysa ikincisi yanlış, birincisi doğrudur.'),
  ('\'Ali gelirse Veli de gelir\' ile \'Veli gelmezse Ali de gelmez\' önermeleri arasındaki ilişki nedir?', 'Eşdeğerdirler', ['Çelişiktirler, biri doğruysa öteki yanlış', 'Karşıttırlar, birlikte doğru olamaz', 'Birbirinden bağımsızdırlar'], 'İkincisi ilkinin kontrapozisyonudur; her durumda aynı doğruluk değerini taşır.'),
  ('\'Bazı öğrenciler sınavı geçti\' ile \'Bazı öğrenciler sınavı geçemedi\' önermeleri arasındaki ilişki nedir?', 'Birlikte yanlış olamazlar', ['Çelişiktirler', 'Birlikte doğru olamazlar ama yanlış olabilirler', 'Eşdeğerdirler'], 'Sınıfın bir kısmı geçip bir kısmı kalabilir (ikisi de doğru); ancak ikisi de yanlış olması için kimse olmaması gerekir (klasik yorumda mümkün değildir).'),
  ('\'Hem Ali hem Veli geldi\' önermesinin olumsuzu hangisidir?', 'Ali gelmedi ya da Veli gelmedi', ['Ali ve Veli gelmedi', 'Ali geldi ama Veli gelmedi, çünkü ya da bağlacı', 'Ali ya da Veli geldi'], 'De Morgan: ¬(p ∧ q) ≡ ¬p ∨ ¬q; en az birinin gelmemesi yeter.'),
  ('\'Ali ya da Veli geldi\' önermesinin olumsuzu hangisidir?', 'Ali de Veli de gelmedi', ['Ali gelmedi ya da Veli gelmedi', 'Ali geldi ama Veli gelmedi', 'Ali ve Veli geldi'], '¬(p ∨ q) ≡ ¬p ∧ ¬q; iki kişinin de gelmemesi gerekir.'),
  ('\'Eğer yağmur yağarsa maç ertelenir\' önermesinin olumsuzu hangisidir?', 'Yağmur yağar ama maç ertelenmez', ['Yağmur yağmaz ve maç ertelenir', 'Yağmur yağmazsa maç ertelenmez', 'Yağmur yağmaz ama maç ertelenmez'], 'Koşullu önermenin olumsuzu, öncülün doğru sonucun yanlış olduğu durumdur.'),
  ('Bir bilim insanı, aynı ilacı verdiği 200 hastanın 190\'ında iyileşme gördüğünde bu sonucu \'ilaç genel olarak etkilidir\' biçiminde genelleştiriyor. Bu genellemenin güvenilirliği hangi bilgiye en çok bağlıdır?', 'Örneklemin hasta nüfusunu temsil edip etmediğine', ['Hastaların adlarının alfabetik sırasına', 'İlacın kutusunun renginin ne olduğuna', 'Çalışmanın yapıldığı binanın büyüklüğüne'], 'Tümevarımsal genellemenin gücü örneklemin boyutu kadar temsil gücüne ve kontrol edilmiş koşullara bağlıdır.'),
  ('Aynı cinsiyet, yaş ve sağlık düzeyindeki iki gruptan yalnızca birine yeni bir gıda katkısı verilip sağlık sonuçları karşılaştırılıyor. Bu düzenek hangi yöntem düşüncesine daha çok uyar?', 'Fark yöntemi', ['Uyuşum yöntemi', 'Artık yöntemi', 'Dolaysız çıkarım'], 'Gruplar bir tek etken dışında benzer tutulursa sonuç farkı o etkene bağlanabilir; bu fark yöntemidir.'),
  ('Beş farklı şehirde yaşayan, farklı mesleklerden birçok kişinin hepsinin kronik bir hastalığa yakalandığı ve ortak noktalarının yalnızca aynı marka su arıtma cihazını kullanmaları olduğu saptanıyor. Bu çıkarım Mill\'in hangi yöntemidir?', 'Uyuşum yöntemi', ['Artık yöntemi', 'Birlikte değişim yöntemi', 'Yanlışlama yöntemi'], 'Durumlar birbirine çok benzemese de hepsinde ortak bulunan tek etken neden aday gösteriliyor; bu uyuşum yöntemidir.'),
  ('Bir ses dalgasının frekansı arttıkça algılanan tonun incelmesi, iki değişkenin birlikte değişmesine dayalı hangi yöntemle açıklanır?', 'Birlikte değişim yöntemi', ['Fark yöntemi', 'Artık yöntemi', 'Tam sayım yöntemi'], 'Bir değişken artarken ötekinin düzenli biçimde değişmesi, aralarında nedensel bağ bulunduğunu düşündürür.'),
  ('Bir bilim insanı, belirli bir bitkinin yalnızca karanlıkta solduğunu gözlemleyip ışığın bitki için gerekli olduğu sonucuna varıyor. Bu çıkarım neden yine de kesin değildir?', 'Başka etkenler (sıcaklık, nem) de eş zamanlı değişmiş olabilir', ['Bitkiler hiç solmaz', 'Işık bitkiler için hiçbir zaman gerekli değildir', 'Gözlem tümdengelimle yapılmıştır'], 'Tümevarımsal nedensel çıkarım, başka etkenlerin kontrol edilmemesi halinde zayıf kalır.'),
  ('\'Bütün metaller ısıtılınca genleşir\' genellemesine ulaşırken yapılan gözlemler \'Bakır ısıtılınca genleşir\', \'Demir ısıtılınca genleşir\' gibi tek tek önermelerdir. Bu önermeler genellemeye nasıl bağlanır?', 'Genellemeyi destekler ama zorunlu kılmaz', ['Genellemeyi kanıtlar ve kesinleştirir', 'Genellemeyi çürütür', 'Genellemeyle ilgisizdir'], 'Tek tek önermeler tümevarımsal destektir; evrensel önerme bunlardan mantıksal olarak zorunlu çıkmaz.'),
  ('İki farklı gezegenin her ikisinin de bir uydusu vardır ve ikisinin de yüzeyinde krater bulunur. Bir uzay bilimcisi \'Birinde su varsa ötekinde de vardır\' diyor. Bu analojinin zayıflığı nedir?', 'Krater ve uydu benzerliklerinin suyun varlığıyla ilgisiz olması', ['Gezegenlerin çok uzak olması', 'Uydu sayısının az olması', 'Kraterlerin gözlenememesi'], 'Analoji benzerliklerin sonuçla ilgili olduğu ölçüde güçlüdür; krater suyun varlığını belirlemez.'),
  ('Bir ilacın hayvan deneylerinde başarılı olması, insanlar için başarısını garanti etmez. Bu durum analojide hangi sorunun örneğidir?', 'Benzerlikler yanında ilgili farkların da bulunması', ['Tam sayım yapılmaması', 'Tanımın döngüsel olması', 'Kıyasın dört terimli olması'], 'Türler arasındaki fizyolojik farklar analojiyi zayıflatır; benzerlik yeterli olmayabilir.'),
  ('Bir mühendis, bir köprünün küçük ölçekli modelini rüzgâr tünelinde sınayıp gerçek köprünün davranışını öngörüyor. Bu çıkarımın dayanağı nedir?', 'Model ile gerçeğin sonuçla ilgili fiziksel özelliklerinin benzerliği', ['Modelin ucuz olması', 'Gerçek köprünün çok büyük olması', 'Rüzgârın hep aynı yönden esmesi'], 'Modelleme, ilgili özelliklerin benzerliğine dayanan güçlü bir analoji kullanımıdır.'),
  ('Bir hakimin, daha önce benzer bir davada verilen kararı ilgili farklar yoksa yeni davada da uygulaması, analojik akıl yürütmenin hangi ilkesine dayanır?', 'Benzer durumlara benzer sonuç uygulanır ilkesine', ['Her dava tek ve eşsizdir ilkesine', 'Önceki kararlar hiç dikkate alınmaz ilkesine', 'Çelişik kararlar eşit sayılır ilkesine'], 'Emsal karar mantığı, benzer olayların benzer biçimde değerlendirilmesini gerektirir.'),
  ('Bir araştırmacı yalnızca üniversite öğrencilerine uygulanan bir deneyin sonuçlarını bütün insanlar için geçerli sayıyor. Bu iddianın dayanağı en çok hangi açıdan sorgulanır?', 'Örneklemin evreni temsil gücü', ['Deneyin tekrar edilebilmesi', 'Sonuçların yayımlanması', 'Katılımcı sayısının çift olması'], 'Genelleme, örneklemin hedef evreni yansıtmasına bağlıdır; belirli bir gruptan yapılan genelleme sınırlıdır.'),
  ('Bir kişi \'Her zaman yaptığım gibi sabah kahvemi içersem günüm iyi geçiyor\' diyor. Bu çıkarımı sınamak için en uygun yol nedir?', 'Kahve içilen ve içilmeyen günleri koşulları kontrol ederek karşılaştırmak', ['Yalnızca iyi geçen günleri saymak', 'Kahvenin markasını değiştirmek', 'Başkalarının fikrini sormak'], 'Neden-sonuç iddiası, hem var hem yok koşullarının karşılaştırılmasıyla sınanabilir.'),
  ('\'Eğer faturayı ödemezsen elektrik kesilir. Elektrik kesilirse buzdolabı çalışmaz. Buzdolabı çalışmazsa yiyecekler bozulur.\' öncüllerinden hangisi geçerli olarak çıkar?', 'Faturayı ödemezsen yiyecekler bozulur', ['Yiyecekler bozulduysa fatura ödenmemiştir', 'Fatura ödenirse yiyecekler bozulmaz', 'Elektrik kesilmediyse fatura ödenmemiştir'], 'Hipotetik kıyas zinciriyle ilk öncül son sonuca bağlanır: fatura ödenmezse yiyecekler bozulur.'),
  ('\'Yağmur yağarsa top oynayamayız. Top oynayamazsak antrenman iptal olur.\' öncüllerine göre \'Antrenman iptal olmadı\' bilgisinden ne çıkarılabilir?', 'Yağmur yağmadı', ['Yağmur yağdı', 'Top oynandı ve yağmur yağdı', 'Hiçbir sonuç çıkmaz'], 'Önce zincirleme koşullu kurulur: yağmur → iptal; sonucun yadsınması öncülün yadsınmasını gerektirir (modus tollens).'),
  ('\'Ya Ali evdedir ya da Burak evdedir. Ali evde değildir. Burak evde değilse Can evdedir.\' Bu bilgilerle kesin olarak hangisi çıkar?', 'Burak şu anda evdedir', ['Can evdedir', 'Hiç kimse evde değildir', 'Ali ile Burak evdedir'], 'Ayrık kıyasla Ali yoksa Burak vardır; Can ile ilgili öncül ise \'Burak yoksa\' koşuluna bağlıdır.'),
  ('\'Ya kazanırız ya da kaybederiz; kazanırsak ödül alırız; kaybedersek ders çıkarırız\' öncülleri verilen bir ikilemin sonucu hangisidir?', 'Ya ödül alırız ya da ders çıkarırız', ['Ödül alırız', 'Ders çıkarırız', 'Hem ödül alırız hem ders çıkarırız'], 'Yapıcı ikilem: iki koşullu ve ayrık öncülden, sonuçların ayrık biçimi çıkar.'),
  ('Bir öğretmen \'Ancak derse katılanlar sınava girebilir\' diyor. Bir öğrencinin sınava girdiği biliniyorsa ne söylenebilir?', 'Derse katılmıştır', ['Derse katılmamıştır', 'Derse katılıp katılmadığı belirsizdir', 'Sınavı geçmiştir'], '\'Ancak p ise q\' kalıbı q → p\'dir: sınava giren derse katılmıştır.'),
  ('\'Ali okula giderse ancak o zaman not alır\' ifadesine göre Ali\'nin not aldığı biliniyorsa ne söylenebilir?', 'Okula gitmiştir', ['Okula gitmemiştir', 'Okula gidip gitmediği belirsizdir', 'Not almak okula gitmeyi gerektirmez'], 'Notun alınması için okula gitmek gerek koşuldur; not alındıysa okula gidilmiştir.'),
  ('\'Bir sayının 10\'a bölünebilmesi için 5\'e bölünebilmesi\' hangi koşuldur?', 'Gerek koşul', ['Yeter koşul', 'Gerek ve yeter koşul', 'Koşul değildir'], '10\'a bölünen her sayı 5\'e bölünür; ancak 15 gibi 5\'e bölünen sayılar 10\'a bölünmez.'),
  ('\'Hiçbir şey olmadan bir şey olmaz\' (ex nihilo nihil fit) ilkesi, hangi mantıksal ilkenin metafizik biçimine yakındır?', 'Yeter neden ilkesi', ['Üçüncü hâlin olmaması', 'Çelişmezlik', 'Özdeşlik'], 'Her şeyin bir nedeni olduğu iddiası yeter neden ilkesinin metafizik karşılığıdır.'),
  ('Bir öğrencinin \'Sınav zor olduğu için kaldım; kolay olsaydı kesinlikle geçerdim\' demesi hangi kıyası taşır?', 'Gizli öncül: kolay sınavda herkes geçer; ancak bu varsayım kanıtsızdır', ['Dört terimli kıyas', 'Ayrık kıyas', 'Totoloji'], 'Cümle, doğrulanmamış bir genel öncüle dayanıyor; entimem yapısındadır.'),
  ('\'Bu görüş öyle saçma ki ona yanıt vermeye değmez\' diyerek karşı argümanı tartışmadan reddetmek hangi hatadır?', 'Taşa başvurma (alay ederek geçiştirme)', ['Ortayı bulma (iki görüşün ortasını doğru sayma)', 'Teksas nişancısı (sonradan hedef çizme)', 'Yanlış denklik'], 'Bir iddiayı gerekçe göstermeden saçma ilan edip reddetmek, onu çürütmek değildir.'),
  ('Bir sunucu, protestocunun sesi yükseldiği için \'Böyle bağıran birinin haklı olması mümkün değil\' diyor. Bu söz hangi hatayı yansıtır?', 'Ton polisliği (üsluba bakıp içeriği dışlama)', ['Kaygan zemin (zincirleme felaket savı)', 'Korkuya başvurma', 'Çoğunluğa başvurma (herkes yapıyor diye doğru sayma)'], 'Söylenişin tonu, iddianın doğruluğunu belirlemez; içerik ayrıca değerlendirilmelidir.'),
  ('\'Ali iyi bir hırsızdır; demek ki iyi bir insandır\' akıl yürütmesinde hata nedir?', '\'İyi\' sözcüğünün farklı bağlamlarda farklı anlam taşımasının gözden kaçırılması', ['Orta terimin dağıtılmaması', 'Öncülün olumsuz olması', 'İki tikel öncül kullanılması'], '\'İyi hırsız\' beceri bildirir; \'iyi insan\' ahlaki nitelik bildirir. İki ifade aynı niteliği taşımaz.'),
  ('Bir kişi \'Şüpheli bir fikir bu, bütün dünya biliyor ki yanlış, o yüzden ayrıca ele almaya gerek yok\' diyor. Bu söylemde hangi iki hata birleşiyor?', 'Çoğunluğa başvurma ve gerekçe göstermeme', ['Kıyasta dört terim ve çelişki', 'Analoji ve tümevarım', 'Altlama ve çelişiklik'], 'Yaygın kanaate dayanmak ve gerekçelendirmeyi reddetmek birlikte ikna edici görünür ama kanıt sunmaz.'),
  ('Bir parti lideri, hükümetin ekonomi politikasını eleştirenlere \'Siz ülkenin kötü gitmesini istiyorsunuz\' diyor. Bu karşılık hangi hatayı yansıtır?', 'Eleştiriyi niyet okumasıyla geçersiz saymak', ['Kumarbaz yanılgısı', 'Tümevarımsal genelleme', 'Ekolojik yanılgı'], 'Eleştirinin içeriğine yanıt vermek yerine eleştirenin niyetine saldırmak, kanıt yerine suçlama kullanmaktır.'),
  ('Bir tartışmada karşıdaki kişinin kanıtını reddetmek için \'Bu kanıt bir kitaptan alınma, kitaplara güvenilmez\' denmesi hangi hatadır?', 'Genelleme yoluyla kaynağı topluca reddetme', ['Kıyasta üçüncü şekil hatası', 'Totoloji kurma', 'Analoji kullanma'], 'Bütün kitapları aynı ölçüde güvenilmez saymak aşırı genelleme; her kaynak ayrı ayrı değerlendirilmelidir.'),
  ('Bir argümanın öncüllerinden birinin \'kabul edilebilir\' sayılmasının ölçütlerinden biri hangisidir?', 'Genel bilgiyle ya da güvenilir kanıtla uyumlu olması', ['Argümanı sunan kişinin ünlü olması', 'Cümlenin kısa olması', 'Çoğunluğun hoşuna gitmesi'], 'Kabul edilebilir öncül, gerekçelendirilebilir ve bilinen gerçeklikle çelişmeyen öncüldür.'),
  ('Birinin \'Kanıt yok, bu yüzden hiç kimse bilemez; o hâlde her görüş eşit derecede doğrudur\' demesi hangi hatadır?', 'Bilgisizlikten eşit değerlilik çıkarma', ['Kaygan zemin', 'Köken safsatası', 'Eşseslilik'], 'Kanıtın yetersizliği iddiaları eşitlemez; farklı görüşler farklı derecelerde destek görür.'),
  ('Bir anketi hazırlayan kişi \'Bu önemli yasaya karşı olan akıldışı insanlara katılıyor musunuz?\' diye soruyor. Bu soru biçimi mantıksal olarak nasıl eleştirilir?', 'Yüklü sözcükler yoluyla yanıtı yönlendiren bir soru olduğu için', ['Çelişik önerme içerdiği için', 'Kıyas biçiminde olduğu için', 'Tümel olumsuz olduğu için'], 'Soru kendi içinde bir değer yargısı taşıyarak yanıtlayanı belirli bir sonuca yönlendirir; tarafsız ölçüm zayıflar.'),
  ('Mantıkta \'bileşik terim\' ile \'yalın terim\' arasındaki ayrım için aşağıdakilerden hangisi doğrudur?', '\'Beyaz kedi\' bileşik, \'kedi\' yalın terimdir', ['\'Kedi\' bileşik, \'beyaz kedi\' yalın terimdir', 'İkisi aynıdır', 'Yalnız soyut terimler bileşik olur'], 'Birden çok niteliği birleştiren terime bileşik, tek bir kavramı gösterene yalın terim denir.'),
  ('\'Okul, öğrencilerin ders gördüğü yerdir\' tanımı hangi açıdan eksik olabilir?', 'Ders gördükleri başka yerleri (kurs, dershane) de kapsayabilir', ['Mecaz içerir', 'Döngüseldir', 'Olumsuz ifade kullanır'], 'Tanım ayırıcı ölçütü yeterince daraltmadığı için fazla geniş kalır.'),
  ('Çeşitli hayvanları kemikli ve kemiksiz diye ikiye ayırdıktan sonra kemiklileri yine yaşadıkları ortama göre ayırmak hangi bölme özelliğini gösterir?', 'Basamaklı (kademeli) bölme: her basamakta tek ölçüt kullanılır', ['Aynı basamakta iki ölçüt karıştırma', 'Bölmenin eksik bırakılması', 'Bölünenin bölümlerle özdeşleşmesi'], 'Her basamakta tek ölçüt kullanıldığı sürece ardışık bölme sorunsuzdur.'),
  ('Bir kütüphaneci kitapları \'roman, ansiklopedi, ciltli kitaplar\' başlıklarıyla ayırıyor. Bu sınıflandırmanın sorunu nedir?', 'Farklı ölçütler karıştırıldığı için bölümler çakışır', ['Bölüm sayısı çok az olduğu için', 'Tanım döngüsel olduğu için', 'Kıyas biçimine uymadığı için'], 'Tür (roman, ansiklopedi) ve biçim (ciltli) farklı ölçütlerdir; bir roman ciltli de olabilir.'),
  ('Bir eşya sınıflandırmasında \'ev eşyası\', \'ofis eşyası\' ve \'diğer\' kategorilerinin bulunması hangi bölme kuralını güvence altına alır?', 'Bölümlerin birleşiminin bölüneni tamamen kapsaması', ['Bölümlerin çakışması', 'Bölünenin içleminin azalması', 'Terimlerin soyutlaşması'], '\'Diğer\' kategorisi hiçbir üyenin dışarıda kalmamasını sağlayarak tamlık kuralını korur.'),
  ('Mantıkta \'zorunlu doğru önerme\' ile \'olgusal doğru önerme\' arasındaki fark nedir?', 'Zorunlu doğru önerme her olanaklı durumda doğrudur, olgusal doğru yalnızca gerçek durumda', ['Olgusal doğru her olanaklı durumda doğrudur', 'İkisi aynıdır', 'Zorunlu doğru önerme yalnız deneyle bulunur'], 'Mantıksal totolojiler zorunlu doğrudur; \'Bugün yağmur yağıyor\' olgusal ve olumsal bir doğruluktur.'),
  ('Çok değerli mantıkta üçüncü bir doğruluk değeri tanımlanmasının amaçlarından biri hangisidir?', 'Henüz belirlenmemiş ya da belirsiz önermeleri değerlendirmek', ['Totolojileri kaldırmak', 'Kıyas şekillerini çoğaltmak', 'Niceleyicileri ortadan kaldırmak'], 'Gelecek olumsallıkları ya da bulanık sınır durumlarını ele almak için doğru ve yanlış dışında ara değer kabul edilir.'),
  ('Bulanık mantıkta \'Hava ılık\' önermesinin doğruluk derecesi 0,6 ise \'Hava ılık değil\' önermesinin derecesi için standart yaklaşım hangisidir?', '0,4', ['0,6', '1', '0'], 'Zadeh\'in standart olumsuzlamasında ¬p\'nin derecesi 1 − p\'dir; 1 − 0,6 = 0,4.'),
  ('Bulanık mantıkta \'ve\' bağlacı için sık kullanılan en küçük değeri alma kuralıyla, derecesi 0,7 olan \'sıcak\' ile 0,4 olan \'nemli\' önermelerinin \'ve\' bileşiği hangi dereceyi alır?', '0,4', ['0,7', '1,1', '0,28'], 'Zadeh\'in standart bağlacında p ∧ q = min(p, q) = 0,4.'),
  ('Aynı bağlaçla \'veya\' için en büyük değeri alma kuralı uygulanırsa 0,7 ve 0,4 dereceli önermelerin \'veya\' bileşiği kaç olur?', '0,7', ['0,4', '1,1', '0,28'], 'Zadeh\'in standart ayrıklığında p ∨ q = max(p, q) = 0,7.'),
  ('Şunlardan hangisi mantıksal bir totolojinin dünya hakkında verdiği bilgiyi en doğru biçimde anlatır?', 'Dünya hakkında hiçbir bilgi vermez; her durumda doğrudur', ['Dünyada olup biteni kesin olarak bildirir', 'Her zaman deneyle doğrulanır', 'Yalnızca yanlış durumları tanımlar'], '\'Yağmur yağıyor ya da yağmıyor\' her durumda doğru olduğundan hava hakkında bilgi içermez.'),
  ('Church ve Turing\'in 1936 tarihli sonuçlarına göre birinci derece yüklem mantığı hakkında hangisi doğrudur?', 'Bir formülün geçerli olup olmadığına her zaman karar veren genel bir yöntem yoktur', ['Her formülün geçerliliği doğruluk tablosuyla belirlenir', 'Yüklem mantığı çelişkilidir', 'Yüklem mantığında hiçbir formül geçerli değildir'], 'Birinci derece mantığın geçerlilik sorunu yarı karar verilebilirdir: geçerliler sıralanabilir ama geçersizler için genel bir karar yöntemi yoktur.'),
  ('\'Bazı mantık bulmacaları kolaydır\' önermesini çürütmek için aşağıdakilerden hangisi gerekir?', 'Hiçbir mantık bulmacasının kolay olmadığını göstermek', ['Bir kolay bulmaca göstermek', 'Bir zor bulmaca göstermek', 'Bulmaca sayısını artırmak'], 'Tikel olumlu önermeyi çürütmek için tümel olumsuz önermeyi (hiçbiri kolay değil) kanıtlamak gerekir; tek örnek tikeli kanıtlar, çürütemez.'),
  ('Öncüllerinden biri yanlış olan geçerli bir argümanın sonucu için ne söylenebilir?', 'Doğru da yanlış da olabilir', ['Kesinlikle yanlıştır', 'Kesinlikle doğrudur', 'Anlamsızdır'], 'Geçerlilik yalnızca doğru öncüllerden doğru sonuç çıkacağını garanti eder; yanlış öncüllerde sonuç hakkında bir şey söylemez.'),
  ('Sembolik mantıkta işlem önceliği ¬ > ∧ > ∨ > → olduğuna göre \'p ∨ q ∧ r\' ifadesi hangi gruplamaya karşılık gelir?', 'p ∨', ['(p ∨ q) ∧ r', '¬(p ∨ q) ∧ r', '(p ∧ q) ∨ r'], '∧ bağlacı ∨\'dan önce işlenir; böylece q ∧ r önce gruplanır.'),
  ('Önceliği ¬ > ∧ > ∨ > → olan bir sistemde \'¬p ∨ q → r\' ifadesi nasıl gruplanır?', '((¬p) ∨ q) → r', ['¬(p ∨ q) → r', '¬p ∨', '¬(p ∨ (q → r))'], 'Önce ¬p, sonra ∨, en son → işlenir.'),
  ('Tek bir önerme değişkeninden (p) kurulabilecek birbirinden farklı doğruluk fonksiyonlarının sayısı kaçtır?', '4', ['2', '3', '8'], 'İki satırlı tabloda her satır D ya da Y olabileceğinden 2² = 4 fonksiyon vardır: p, ¬p, daima doğru ve daima yanlış.'),
  ('Üç önerme değişkeninden kurulabilecek farklı doğruluk fonksiyonlarının sayısı kaçtır?', '256', ['64', '128', '512'], 'Tabloda 2³ = 8 satır vardır ve her satır iki değer alabileceğinden 2⁸ = 256 fonksiyon bulunur.'),
  ('Hangi bağlaç kümesi, bütün ikili doğruluk fonksiyonlarını kurabilmek bakımından (fonksiyonel tamlık) yeterlidir?', '{¬, ∧}', ['{∧, ∨}', '{→}', '{↔}'], 'Olumsuzlama ve ve ile veya (De Morgan) ve koşullu bağlaçlar kurulabilir; yalnız ∧ ile ∨ olumsuzlamasız kalır.'),
];
